const POEMS_ZH = [
  { id: "poem:zh:001", title: "终南别业", author: "王维", lines: ["行到水穷处，坐看云起时。", "偶然值林叟，谈笑无还期。"] },
  { id: "poem:zh:002", title: "登鹳雀楼", author: "王之涣", lines: ["白日依山尽，黄河入海流。", "欲穷千里目，更上一层楼。"] },
  { id: "poem:zh:003", title: "静夜思", author: "李白", lines: ["床前明月光，疑是地上霜。", "举头望明月，低头思故乡。"] },
  { id: "poem:zh:004", title: "春晓", author: "孟浩然", lines: ["春眠不觉晓，处处闻啼鸟。", "夜来风雨声，花落知多少。"] },
  { id: "poem:zh:005", title: "江雪", author: "柳宗元", lines: ["千山鸟飞绝，万径人踪灭。", "孤舟蓑笠翁，独钓寒江雪。"] },
  { id: "poem:zh:006", title: "枫桥夜泊", author: "张继", lines: ["月落乌啼霜满天，江枫渔火对愁眠。", "姑苏城外寒山寺，夜半钟声到客船。"] },
  { id: "poem:zh:007", title: "山居秋暝", author: "王维", lines: ["空山新雨后，天气晚来秋。", "明月松间照，清泉石上流。"] },
  { id: "poem:zh:008", title: "相思", author: "王维", lines: ["红豆生南国，春来发几枝。", "愿君多采撷，此物最相思。"] },
  { id: "poem:zh:009", title: "登幽州台歌", author: "陈子昂", lines: ["前不见古人，后不见来者。", "念天地之悠悠，独怆然而涕下。"] },
  { id: "poem:zh:010", title: "早发白帝城", author: "李白", lines: ["朝辞白帝彩云间，千里江陵一日还。", "两岸猿声啼不住，轻舟已过万重山。"] },
  { id: "poem:zh:011", title: "游子吟", author: "孟郊", lines: ["慈母手中线，游子身上衣。", "临行密密缝，意恐迟迟归。"] },
  { id: "poem:zh:012", title: "赋得古原草送别（节选）", author: "白居易", lines: ["离离原上草，一岁一枯荣。", "野火烧不尽，春风吹又生。"] },
  { id: "poem:zh:013", title: "鹿柴", author: "王维", lines: ["空山不见人，但闻人语响。", "返景入深林，复照青苔上。"] },
  { id: "poem:zh:014", title: "悯农（其二）", author: "李绅", lines: ["锄禾日当午，汗滴禾下土。", "谁知盘中餐，粒粒皆辛苦。"] },
  { id: "poem:zh:015", title: "春望", author: "杜甫", lines: ["国破山河在，城春草木深。", "感时花溅泪，恨别鸟惊心。"] },
  { id: "poem:zh:016", title: "月下独酌（其一）", author: "李白", lines: ["花间一壶酒，独酌无相亲。", "举杯邀明月，对影成三人。"] },
  { id: "poem:zh:017", title: "望庐山瀑布", author: "李白", lines: ["日照香炉生紫烟，遥看瀑布挂前川。", "飞流直下三千尺，疑是银河落九天。"] },
  { id: "poem:zh:018", title: "黄鹤楼送孟浩然之广陵", author: "李白", lines: ["故人西辞黄鹤楼，烟花三月下扬州。", "孤帆远影碧空尽，唯见长江天际流。"] },
  { id: "poem:zh:019", title: "送元二使安西", author: "王维", lines: ["渭城朝雨浥轻尘，客舍青青柳色新。", "劝君更尽一杯酒，西出阳关无故人。"] },
  { id: "poem:zh:020", title: "九月九日忆山东兄弟", author: "王维", lines: ["独在异乡为异客，每逢佳节倍思亲。", "遥知兄弟登高处，遍插茱萸少一人。"] },
  { id: "poem:zh:021", title: "绝句", author: "杜甫", lines: ["两个黄鹂鸣翠柳，一行白鹭上青天。", "窗含西岭千秋雪，门泊东吴万里船。"] },
  { id: "poem:zh:022", title: "春夜喜雨", author: "杜甫", lines: ["好雨知时节，当春乃发生。", "随风潜入夜，润物细无声。"] },
  { id: "poem:zh:023", title: "泊船瓜洲", author: "王安石", lines: ["京口瓜洲一水间，钟山只隔数重山。", "春风又绿江南岸，明月何时照我还。"] },
  { id: "poem:zh:024", title: "题西林壁", author: "苏轼", lines: ["横看成岭侧成峰，远近高低各不同。", "不识庐山真面目，只缘身在此山中。"] },
  { id: "poem:zh:025", title: "饮湖上初晴后雨", author: "苏轼", lines: ["水光潋滟晴方好，山色空蒙雨亦奇。", "欲把西湖比西子，淡妆浓抹总相宜。"] },
  { id: "poem:zh:026", title: "元日", author: "王安石", lines: ["爆竹声中一岁除，春风送暖入屠苏。", "千门万户曈曈日，总把新桃换旧符。"] },
  { id: "poem:zh:027", title: "清明", author: "杜牧", lines: ["清明时节雨纷纷，路上行人欲断魂。", "借问酒家何处有，牧童遥指杏花村。"] },
  { id: "poem:zh:028", title: "江南春", author: "杜牧", lines: ["千里莺啼绿映红，水村山郭酒旗风。", "南朝四百八十寺，多少楼台烟雨中。"] },
  { id: "poem:zh:029", title: "山行", author: "杜牧", lines: ["远上寒山石径斜，白云生处有人家。", "停车坐爱枫林晚，霜叶红于二月花。"] },
  { id: "poem:zh:030", title: "咏柳", author: "贺知章", lines: ["碧玉妆成一树高，万条垂下绿丝绦。", "不知细叶谁裁出，二月春风似剪刀。"] },
  { id: "poem:zh:031", title: "回乡偶书", author: "贺知章", lines: ["少小离家老大回，乡音无改鬓毛衰。", "儿童相见不相识，笑问客从何处来。"] },
  { id: "poem:zh:032", title: "咏鹅", author: "骆宾王", lines: ["鹅，鹅，鹅，曲项向天歌。", "白毛浮绿水，红掌拨清波。"] },
  { id: "poem:zh:033", title: "登飞来峰", author: "王安石", lines: ["飞来山上千寻塔，闻说鸡鸣见日升。", "不畏浮云遮望眼，自缘身在最高层。"] },
  { id: "poem:zh:034", title: "夏日绝句", author: "李清照", lines: ["生当作人杰，死亦为鬼雄。", "至今思项羽，不肯过江东。"] },
  { id: "poem:zh:035", title: "示儿", author: "陆游", lines: ["死去元知万事空，但悲不见九州同。", "王师北定中原日，家祭无忘告乃翁。"] },
  { id: "poem:zh:036", title: "游山西村", author: "陆游", lines: ["莫笑农家腊酒浑，丰年留客足鸡豚。", "山重水复疑无路，柳暗花明又一村。"] },
  { id: "poem:zh:037", title: "石灰吟", author: "于谦", lines: ["千锤万凿出深山，烈火焚烧若等闲。", "粉骨碎身浑不怕，要留清白在人间。"] },
  { id: "poem:zh:038", title: "竹石", author: "郑燮", lines: ["咬定青山不放松，立根原在破岩中。", "千磨万击还坚劲，任尔东西南北风。"] },
  { id: "poem:zh:039", title: "己亥杂诗（其五）", author: "龚自珍", lines: ["浩荡离愁白日斜，吟鞭东指即天涯。", "落红不是无情物，化作春泥更护花。"] },
  { id: "poem:zh:040", title: "夜雨寄北", author: "李商隐", lines: ["君问归期未有期，巴山夜雨涨秋池。", "何当共剪西窗烛，却话巴山夜雨时。"] },
  { id: "poem:zh:041", title: "无题（节选）", author: "李商隐", lines: ["相见时难别亦难，东风无力百花残。", "春蚕到死丝方尽，蜡炬成灰泪始干。"] },
  { id: "poem:zh:042", title: "竹里馆", author: "王维", lines: ["独坐幽篁里，弹琴复长啸。", "深林人不知，明月来相照。"] },
  { id: "poem:zh:043", title: "鸟鸣涧", author: "王维", lines: ["人闲桂花落，夜静春山空。", "月出惊山鸟，时鸣春涧中。"] },
  { id: "poem:zh:044", title: "使至塞上", author: "王维", lines: ["征蓬出汉塞，归雁入胡天。", "大漠孤烟直，长河落日圆。"] },
  { id: "poem:zh:045", title: "送别", author: "王维", lines: ["下马饮君酒，问君何所之。", "君言不得意，归卧南山陲。"] },
  { id: "poem:zh:046", title: "将进酒（节选）", author: "李白", lines: ["君不见黄河之水天上来，奔流到海不复回。", "君不见高堂明镜悲白发，朝如青丝暮成雪。"] },
  { id: "poem:zh:047", title: "行路难（其一）（节选）", author: "李白", lines: ["欲渡黄河冰塞川，将登太行雪满山。", "长风破浪会有时，直挂云帆济沧海。"] },
  { id: "poem:zh:048", title: "望天门山", author: "李白", lines: ["天门中断楚江开，碧水东流至此回。", "两岸青山相对出，孤帆一片日边来。"] },
  { id: "poem:zh:049", title: "独坐敬亭山", author: "李白", lines: ["众鸟高飞尽，孤云独去闲。", "相看两不厌，只有敬亭山。"] },
  { id: "poem:zh:050", title: "赠汪伦", author: "李白", lines: ["李白乘舟将欲行，忽闻岸上踏歌声。", "桃花潭水深千尺，不及汪伦送我情。"] },
  { id: "poem:zh:051", title: "闻王昌龄左迁龙标遥有此寄", author: "李白", lines: ["杨花落尽子规啼，闻道龙标过五溪。", "我寄愁心与明月，随君直到夜郎西。"] },
  { id: "poem:zh:052", title: "登高", author: "杜甫", lines: ["风急天高猿啸哀，渚清沙白鸟飞回。", "无边落木萧萧下，不尽长江滚滚来。"] },
  { id: "poem:zh:053", title: "月夜忆舍弟", author: "杜甫", lines: ["戍鼓断人行，边秋一雁声。", "露从今夜白，月是故乡明。"] },
  { id: "poem:zh:054", title: "江南逢李龟年", author: "杜甫", lines: ["岐王宅里寻常见，崔九堂前几度闻。", "正是江南好风景，落花时节又逢君。"] },
  { id: "poem:zh:055", title: "赠花卿", author: "杜甫", lines: ["锦城丝管日纷纷，半入江风半入云。", "此曲只应天上有，人间能得几回闻。"] },
  { id: "poem:zh:056", title: "江畔独步寻花（其六）", author: "杜甫", lines: ["黄四娘家花满蹊，千朵万朵压枝低。", "留连戏蝶时时舞，自在娇莺恰恰啼。"] },
  { id: "poem:zh:057", title: "闻官军收河南河北", author: "杜甫", lines: ["剑外忽传收蓟北，初闻涕泪满衣裳。", "却看妻子愁何在，漫卷诗书喜欲狂。"] },
  { id: "poem:zh:058", title: "泊秦淮", author: "杜牧", lines: ["烟笼寒水月笼沙，夜泊秦淮近酒家。", "商女不知亡国恨，隔江犹唱后庭花。"] },
  { id: "poem:zh:059", title: "秋夕", author: "杜牧", lines: ["银烛秋光冷画屏，轻罗小扇扑流萤。", "天阶夜色凉如水，卧看牵牛织女星。"] },
  { id: "poem:zh:060", title: "赤壁", author: "杜牧", lines: ["折戟沉沙铁未销，自将磨洗认前朝。", "东风不与周郎便，铜雀春深锁二乔。"] },
  { id: "poem:zh:061", title: "寄扬州韩绰判官", author: "杜牧", lines: ["青山隐隐水迢迢，秋尽江南草未凋。", "二十四桥明月夜，玉人何处教吹箫。"] },
  { id: "poem:zh:062", title: "锦瑟", author: "李商隐", lines: ["锦瑟无端五十弦，一弦一柱思华年。", "庄生晓梦迷蝴蝶，望帝春心托杜鹃。"] },
  { id: "poem:zh:063", title: "登乐游原", author: "李商隐", lines: ["向晚意不适，驱车登古原。", "夕阳无限好，只是近黄昏。"] },
  { id: "poem:zh:064", title: "贾生", author: "李商隐", lines: ["宣室求贤访逐臣，贾生才调更无伦。", "可怜夜半虚前席，不问苍生问鬼神。"] },
  { id: "poem:zh:065", title: "问刘十九", author: "白居易", lines: ["绿蚁新醅酒，红泥小火炉。", "晚来天欲雪，能饮一杯无。"] },
  { id: "poem:zh:066", title: "大林寺桃花", author: "白居易", lines: ["人间四月芳菲尽，山寺桃花始盛开。", "长恨春归无觅处，不知转入此中来。"] },
  { id: "poem:zh:067", title: "暮江吟", author: "白居易", lines: ["一道残阳铺水中，半江瑟瑟半江红。", "可怜九月初三夜，露似真珠月似弓。"] },
  { id: "poem:zh:068", title: "钱塘湖春行", author: "白居易", lines: ["几处早莺争暖树，谁家新燕啄春泥。", "乱花渐欲迷人眼，浅草才能没马蹄。"] },
  { id: "poem:zh:069", title: "过故人庄", author: "孟浩然", lines: ["故人具鸡黍，邀我至田家。", "绿树村边合，青山郭外斜。"] },
  { id: "poem:zh:070", title: "宿建德江", author: "孟浩然", lines: ["移舟泊烟渚，日暮客愁新。", "野旷天低树，江清月近人。"] },
  { id: "poem:zh:071", title: "望洞庭湖赠张丞相", author: "孟浩然", lines: ["八月湖水平，涵虚混太清。", "气蒸云梦泽，波撼岳阳城。"] },
  { id: "poem:zh:072", title: "出塞（其一）", author: "王昌龄", lines: ["秦时明月汉时关，万里长征人未还。", "但使龙城飞将在，不教胡马度阴山。"] },
  { id: "poem:zh:073", title: "芙蓉楼送辛渐", author: "王昌龄", lines: ["寒雨连江夜入吴，平明送客楚山孤。", "洛阳亲友如相问，一片冰心在玉壶。"] },
  { id: "poem:zh:074", title: "从军行（其四）", author: "王昌龄", lines: ["青海长云暗雪山，孤城遥望玉门关。", "黄沙百战穿金甲，不破楼兰终不还。"] },
  { id: "poem:zh:075", title: "闺怨", author: "王昌龄", lines: ["闺中少妇不知愁，春日凝妆上翠楼。", "忽见陌头杨柳色，悔教夫婿觅封侯。"] },
  { id: "poem:zh:076", title: "别董大（其一）", author: "高适", lines: ["千里黄云白日曛，北风吹雁雪纷纷。", "莫愁前路无知己，天下谁人不识君。"] },
  { id: "poem:zh:077", title: "白雪歌送武判官归京（节选）", author: "岑参", lines: ["北风卷地白草折，胡天八月即飞雪。", "忽如一夜春风来，千树万树梨花开。"] },
  { id: "poem:zh:078", title: "逢入京使", author: "岑参", lines: ["故园东望路漫漫，双袖龙钟泪不干。", "马上相逢无纸笔，凭君传语报平安。"] },
  { id: "poem:zh:079", title: "凉州词", author: "王翰", lines: ["葡萄美酒夜光杯，欲饮琵琶马上催。", "醉卧沙场君莫笑，古来征战几人回。"] },
  { id: "poem:zh:080", title: "黄鹤楼", author: "崔颢", lines: ["昔人已乘黄鹤去，此地空余黄鹤楼。", "黄鹤一去不复返，白云千载空悠悠。"] },
  { id: "poem:zh:081", title: "逢雪宿芙蓉山主人", author: "刘长卿", lines: ["日暮苍山远，天寒白屋贫。", "柴门闻犬吠，风雪夜归人。"] },
  { id: "poem:zh:082", title: "送灵澈上人", author: "刘长卿", lines: ["苍苍竹林寺，杳杳钟声晚。", "荷笠带斜阳，青山独归远。"] },
  { id: "poem:zh:083", title: "滁州西涧", author: "韦应物", lines: ["独怜幽草涧边生，上有黄鹂深树鸣。", "春潮带雨晚来急，野渡无人舟自横。"] },
  { id: "poem:zh:084", title: "秋夜寄邱员外", author: "韦应物", lines: ["怀君属秋夜，散步咏凉天。", "空山松子落，幽人应未眠。"] },
  { id: "poem:zh:085", title: "早春呈水部张十八员外", author: "韩愈", lines: ["天街小雨润如酥，草色遥看近却无。", "最是一年春好处，绝胜烟柳满皇都。"] },
  { id: "poem:zh:086", title: "左迁至蓝关示侄孙湘（节选）", author: "韩愈", lines: ["一封朝奏九重天，夕贬潮州路八千。", "云横秦岭家何在，雪拥蓝关马不前。"] },
  { id: "poem:zh:087", title: "乌衣巷", author: "刘禹锡", lines: ["朱雀桥边野草花，乌衣巷口夕阳斜。", "旧时王谢堂前燕，飞入寻常百姓家。"] },
  { id: "poem:zh:088", title: "秋词（其一）", author: "刘禹锡", lines: ["自古逢秋悲寂寥，我言秋日胜春朝。", "晴空一鹤排云上，便引诗情到碧霄。"] },
  { id: "poem:zh:089", title: "望洞庭", author: "刘禹锡", lines: ["湖光秋月两相和，潭面无风镜未磨。", "遥望洞庭山水翠，白银盘里一青螺。"] },
  { id: "poem:zh:090", title: "竹枝词（其一）", author: "刘禹锡", lines: ["杨柳青青江水平，闻郎江上唱歌声。", "东边日出西边雨，道是无晴却有晴。"] },
  { id: "poem:zh:091", title: "离思（其四）", author: "元稹", lines: ["曾经沧海难为水，除却巫山不是云。", "取次花丛懒回顾，半缘修道半缘君。"] },
  { id: "poem:zh:092", title: "行宫", author: "元稹", lines: ["寥落古行宫，宫花寂寞红。", "白头宫女在，闲坐说玄宗。"] },
  { id: "poem:zh:093", title: "雁门太守行（节选）", author: "李贺", lines: ["黑云压城城欲摧，甲光向日金鳞开。", "角声满天秋色里，塞上燕脂凝夜紫。"] },
  { id: "poem:zh:094", title: "马诗（其五）", author: "李贺", lines: ["大漠沙如雪，燕山月似钩。", "何当金络脑，快走踏清秋。"] },
  { id: "poem:zh:095", title: "商山早行", author: "温庭筠", lines: ["晨起动征铎，客行悲故乡。", "鸡声茅店月，人迹板桥霜。"] },
  { id: "poem:zh:096", title: "春江花月夜（节选）", author: "张若虚", lines: ["春江潮水连海平，海上明月共潮生。", "滟滟随波千万里，何处春江无月明。"] },
  { id: "poem:zh:097", title: "望月怀远", author: "张九龄", lines: ["海上生明月，天涯共此时。", "情人怨遥夜，竟夕起相思。"] },
  { id: "poem:zh:098", title: "送杜少府之任蜀州（节选）", author: "王勃", lines: ["与君离别意，同是宦游人。", "海内存知己，天涯若比邻。"] },
  { id: "poem:zh:099", title: "山中", author: "王勃", lines: ["长江悲已滞，万里念将归。", "况属高风晚，山山黄叶飞。"] },
  { id: "poem:zh:100", title: "从军行", author: "杨炯", lines: ["烽火照西京，心中自不平。", "牙璋辞凤阙，铁骑绕龙城。"] },
  { id: "poem:zh:101", title: "渡汉江", author: "宋之问", lines: ["岭外音书断，经冬复历春。", "近乡情更怯，不敢问来人。"] },
  { id: "poem:zh:102", title: "登科后", author: "孟郊", lines: ["昔日龌龊不足夸，今朝放荡思无涯。", "春风得意马蹄疾，一日看尽长安花。"] },
  { id: "poem:zh:103", title: "渔翁", author: "柳宗元", lines: ["渔翁夜傍西岩宿，晓汲清湘燃楚竹。", "烟销日出不见人，欸乃一声山水绿。"] },
  { id: "poem:zh:104", title: "题李凝幽居", author: "贾岛", lines: ["闲居少邻并，草径入荒园。", "鸟宿池边树，僧敲月下门。"] },
  { id: "poem:zh:105", title: "寻隐者不遇", author: "贾岛", lines: ["松下问童子，言师采药去。", "只在此山中，云深不知处。"] },
  { id: "poem:zh:106", title: "秋思", author: "张籍", lines: ["洛阳城里见秋风，欲作家书意万重。", "复恐匆匆说不尽，行人临发又开封。"] },
  { id: "poem:zh:107", title: "十五夜望月", author: "王建", lines: ["中庭地白树栖鸦，冷露无声湿桂花。", "今夜月明人尽望，不知秋思落谁家。"] },
  { id: "poem:zh:108", title: "江南曲", author: "李益", lines: ["嫁得瞿塘贾，朝朝误妾期。", "早知潮有信，嫁与弄潮儿。"] },
  { id: "poem:zh:109", title: "春望词（其一）", author: "薛涛", lines: ["花开不同赏，花落不同悲。", "欲问相思处，花开花落时。"] },
  { id: "poem:zh:110", title: "寒食", author: "韩翃", lines: ["春城无处不飞花，寒食东风御柳斜。", "日暮汉宫传蜡烛，轻烟散入五侯家。"] },
  { id: "poem:zh:111", title: "塞下曲（其三）", author: "卢纶", lines: ["月黑雁飞高，单于夜遁逃。", "欲将轻骑逐，大雪满弓刀。"] },
];

/* ---------- Poems: English (public domain) ---------- */
const POEMS_EN = [
  { id: "poem:en:001", title: "The Road Not Taken", author: "Robert Frost", lines: ["Two roads diverged in a wood, and I,", "I took the one less traveled by,", "And that has made all the difference."] },
  { id: "poem:en:002", title: "Hope is the thing with feathers", author: "Emily Dickinson", lines: ["Hope is the thing with feathers", "That perches in the soul,", "And sings the tune without the words,", "And never stops at all."] },
  { id: "poem:en:003", title: "A Psalm of Life", author: "Henry Wadsworth Longfellow", lines: ["Life is real! Life is earnest!", "And the grave is not its goal;", "Dust thou art, to dust returnest,", "Was not spoken of the soul."] },
  { id: "poem:en:004", title: "If—", author: "Rudyard Kipling", lines: ["If you can keep your head when all about you", "Are losing theirs and blaming it on you,", "If you can trust yourself when all men doubt you,", "But make allowance for their doubting too."] },
  { id: "poem:en:005", title: "Sonnet 18", author: "William Shakespeare", lines: ["Shall I compare thee to a summer's day?", "Thou art more lovely and more temperate:", "Rough winds do shake the darling buds of May,", "And summer's lease hath all too short a date."] },
  { id: "poem:en:006", title: "Ozymandias", author: "Percy Bysshe Shelley", lines: ["I met a traveller from an antique land,", "Who said: Two vast and trunkless legs of stone", "Stand in the desert. Near them, on the sand,", "Half sunk a shattered visage lies."] },
  { id: "poem:en:007", title: "The Tyger", author: "William Blake", lines: ["Tyger Tyger, burning bright,", "In the forests of the night;", "What immortal hand or eye,", "Could frame thy fearful symmetry?"] },
  { id: "poem:en:008", title: "Because I could not stop for Death", author: "Emily Dickinson", lines: ["Because I could not stop for Death,", "He kindly stopped for me;", "The Carriage held but just Ourselves", "And Immortality."] },
  { id: "poem:en:009", title: "Invictus", author: "William Ernest Henley", lines: ["Out of the night that covers me,", "Black as the pit from pole to pole,", "I thank whatever gods may be", "For my unconquerable soul."] },
  { id: "poem:en:010", title: "Daffodils", author: "William Wordsworth", lines: ["I wandered lonely as a cloud", "That floats on high o'er vales and hills,", "When all at once I saw a crowd,", "A host, of golden daffodils."] },
  { id: "poem:en:011", title: "Annabel Lee", author: "Edgar Allan Poe", lines: ["It was many and many a year ago,", "In a kingdom by the sea,", "That a maiden there lived whom you may know", "By the name of Annabel Lee."] },
  { id: "poem:en:012", title: "A Light exists in Spring", author: "Emily Dickinson", lines: ["A Light exists in Spring", "Not present on the Year", "At any other period,", "When March is scarcely here."] },
  { id: "poem:en:013", title: "The New Colossus", author: "Emma Lazarus", lines: ["Give me your tired, your poor,", "Your huddled masses yearning to breathe free,", "The wretched refuse of your teeming shore.", "Send these, the homeless, tempest-tost to me."] },
  { id: "poem:en:014", title: "Sonnet 116", author: "William Shakespeare", lines: ["Let me not to the marriage of true minds", "Admit impediments. Love is not love", "Which alters when it alteration finds,", "Or bends with the remover to remove."] },
  { id: "poem:en:015", title: "Sonnet 29", author: "William Shakespeare", lines: ["When, in disgrace with fortune and men's eyes,", "I all alone beweep my outcast state,", "And trouble deaf heaven with my bootless cries,", "And look upon myself and curse my fate."] },
  { id: "poem:en:016", title: "London", author: "William Blake", lines: ["I wander thro' each charter'd street,", "Near where the charter'd Thames does flow,", "And mark in every face I meet", "Marks of weakness, marks of woe."] },
  { id: "poem:en:017", title: "A Poison Tree", author: "William Blake", lines: ["I was angry with my friend:", "I told my wrath, my wrath did end.", "I was angry with my foe:", "I told it not, my wrath did grow."] },
  { id: "poem:en:018", title: "The World Is Too Much with Us", author: "William Wordsworth", lines: ["The world is too much with us; late and soon,", "Getting and spending, we lay waste our powers;", "Little we see in Nature that is ours;", "We have given our hearts away, a sordid boon!"] },
  { id: "poem:en:019", title: "My Heart Leaps Up", author: "William Wordsworth", lines: ["My heart leaps up when I behold", "A rainbow in the sky:", "So was it when my life began;", "So is it now I am a man."] },
  { id: "poem:en:020", title: "Kubla Khan", author: "Samuel Taylor Coleridge", lines: ["In Xanadu did Kubla Khan", "A stately pleasure-dome decree:", "Where Alph, the sacred river, ran", "Through caverns measureless to man", "Down to a sunless sea."] },
  { id: "poem:en:021", title: "Ode to the West Wind", author: "Percy Bysshe Shelley", lines: ["O wild West Wind, thou breath of Autumn's being,", "Thou, from whose unseen presence the leaves dead", "Are driven, like ghosts from an enchanter fleeing."] },
  { id: "poem:en:022", title: "To a Skylark", author: "Percy Bysshe Shelley", lines: ["Hail to thee, blithe Spirit!", "Bird thou never wert,", "That from heaven, or near it,", "Pourest thy full heart."] },
  { id: "poem:en:023", title: "Ode to a Nightingale", author: "John Keats", lines: ["My heart aches, and a drowsy numbness pains", "My sense, as though of hemlock I had drunk,", "Or emptied some dull opiate to the drains."] },
  { id: "poem:en:024", title: "To Autumn", author: "John Keats", lines: ["Season of mists and mellow fruitfulness,", "Close bosom-friend of the maturing sun;", "Conspiring with him how to load and bless", "With fruit the vines that round the thatch-eaves run."] },
  { id: "poem:en:025", title: "On First Looking into Chapman's Homer", author: "John Keats", lines: ["Much have I travell'd in the realms of gold,", "And many goodly states and kingdoms seen;", "Round many western islands have I been", "Which bards in fealty to Apollo hold."] },
  { id: "poem:en:026", title: "She Walks in Beauty", author: "Lord Byron", lines: ["She walks in beauty, like the night", "Of cloudless climes and starry skies;", "And all that's best of dark and bright", "Meet in her aspect and her eyes."] },
  { id: "poem:en:027", title: "Ulysses", author: "Alfred, Lord Tennyson", lines: ["I cannot rest from travel: I will drink", "Life to the lees: All times I have enjoy'd", "Greatly, have suffer'd greatly, both with those", "That loved me, and alone."] },
  { id: "poem:en:028", title: "Crossing the Bar", author: "Alfred, Lord Tennyson", lines: ["Sunset and evening star,", "And one clear call for me!", "And may there be no moaning of the bar,", "When I put out to sea."] },
  { id: "poem:en:029", title: "Sonnet 43", author: "Elizabeth Barrett Browning", lines: ["How do I love thee? Let me count the ways.", "I love thee to the depth and breadth and height", "My soul can reach, when feeling out of sight", "For the ends of being and ideal grace."] },
  { id: "poem:en:030", title: "O Captain! My Captain!", author: "Walt Whitman", lines: ["O Captain! my Captain! our fearful trip is done,", "The ship has weather'd every rack, the prize we sought is won,", "The port is near, the bells I hear, the people all exulting."] },
  { id: "poem:en:031", title: "Song of Myself (excerpt)", author: "Walt Whitman", lines: ["I celebrate myself, and sing myself,", "And what I assume you shall assume,", "For every atom belonging to me as good belongs to you."] },
  { id: "poem:en:032", title: "The Raven", author: "Edgar Allan Poe", lines: ["Once upon a midnight dreary, while I pondered, weak and weary,", "Over many a quaint and curious volume of forgotten lore—", "While I nodded, nearly napping, suddenly there came a tapping."] },
  { id: "poem:en:033", title: "Stopping by Woods on a Snowy Evening", author: "Robert Frost", lines: ["Whose woods these are I think I know.", "His house is in the village though;", "He will not see me stopping here", "To watch his woods fill up with snow."] },
  { id: "poem:en:034", title: "Fire and Ice", author: "Robert Frost", lines: ["Some say the world will end in fire,", "Some say in ice.", "From what I've tasted of desire", "I hold with those who favor fire."] },
  { id: "poem:en:035", title: "Nothing Gold Can Stay", author: "Robert Frost", lines: ["Nature's first green is gold,", "Her hardest hue to hold.", "Her early leaf's a flower;", "But only so an hour."] },
  { id: "poem:en:036", title: "I'm Nobody! Who are you?", author: "Emily Dickinson", lines: ["I'm Nobody! Who are you?", "Are you — Nobody — too?", "Then there's a pair of us!", "Don't tell! they'd advertise — you know!"] },
  { id: "poem:en:037", title: "A Bird, came down the Walk", author: "Emily Dickinson", lines: ["A Bird, came down the Walk —", "He did not know I saw —", "He bit an Angle Worm in halves", "And ate the fellow, raw."] },
  { id: "poem:en:038", title: "The Lake Isle of Innisfree", author: "W. B. Yeats", lines: ["I will arise and go now, and go to Innisfree,", "And a small cabin build there, of clay and wattles made:", "Nine bean-rows will I have there, a hive for the honey-bee;", "And live alone in the bee-loud glade."] },
  { id: "poem:en:039", title: "He Wishes for the Cloths of Heaven", author: "W. B. Yeats", lines: ["Had I the heavens' embroidered cloths,", "Enwrought with golden and silver light,", "The blue and the dim and the dark cloths", "Of night and light and the half-light."] },
  { id: "poem:en:040", title: "When You Are Old", author: "W. B. Yeats", lines: ["When you are old and grey and full of sleep,", "And nodding by the fire, take down this book,", "And slowly read, and dream of the soft look", "Your eyes had once, and of their shadows deep."] },
  { id: "poem:en:041", title: "Remember", author: "Christina Rossetti", lines: ["Remember me when I am gone away,", "Gone far away into the silent land;", "When you can no more hold me by the hand,", "Nor I half turn to go yet turning stay."] },
  { id: "poem:en:042", title: "Meditation XVII (excerpt)", author: "John Donne", lines: ["No man is an island,", "Entire of itself;", "Every man is a piece of the continent,", "A part of the main."] },
  { id: "poem:en:043", title: "On His Blindness", author: "John Milton", lines: ["When I consider how my light is spent,", "Ere half my days, in this dark world and wide,", "And that one Talent which is death to hide", "Lodged with me useless, though my Soul more bent."] },
  { id: "poem:en:044", title: "To the Virgins, to Make Much of Time", author: "Robert Herrick", lines: ["Gather ye rosebuds while ye may,", "Old Time is still a-flying;", "And this same flower that smiles today", "Tomorrow will be dying."] },
  { id: "poem:en:045", title: "To His Coy Mistress", author: "Andrew Marvell", lines: ["Had we but world enough and time,", "This coyness, lady, were no crime.", "We would sit down, and think which way", "To walk, and pass our long love's day."] },
  { id: "poem:en:046", title: "A Red, Red Rose", author: "Robert Burns", lines: ["O my Luve is like a red, red rose", "That's newly sprung in June;", "O my Luve is like the melody", "That's sweetly played in tune."] },
  { id: "poem:en:047", title: "Elegy Written in a Country Churchyard", author: "Thomas Gray", lines: ["The curfew tolls the knell of parting day,", "The lowing herd wind slowly o'er the lea,", "The plowman homeward plods his weary way,", "And leaves the world to darkness and to me."] },
  { id: "poem:en:048", title: "Loveliest of Trees", author: "A. E. Housman", lines: ["Loveliest of trees, the cherry now", "Is hung with bloom along the bough,", "And stands about the woodland ride", "Wearing white for Eastertide."] },
  { id: "poem:en:049", title: "There Will Come Soft Rains", author: "Sara Teasdale", lines: ["There will come soft rains and the smell of the ground,", "And swallows circling with their shimmering sound;", "And frogs in the pools singing at night,", "And wild plum trees in tremulous white."] },
];

/* ---------- History: on this day, keyed by MM-DD ---------- */
const HISTORY = {
  "01-01": { year: 1863, zh: "林肯签署《解放黑奴宣言》生效，美国南方各州的奴隶获得法律上的自由。", en: "Lincoln's Emancipation Proclamation takes effect, legally freeing enslaved people in the Confederate states." },
  "01-27": { year: 1880, zh: "爱迪生获得白炽电灯专利，一盏能连续点亮的灯泡走进千家万户的倒计时开始了。", en: "Thomas Edison receives a patent for the incandescent electric lamp." },
  "02-11": { year: 1990, zh: "曼德拉在被监禁 27 年后走出监狱，南非种族隔离制度走向终结。", en: "Nelson Mandela is released after 27 years in prison, hastening the end of apartheid in South Africa." },
  "03-14": { year: 1879, zh: "爱因斯坦出生于德国乌尔姆。这一天后来也成了圆周率日。", en: "Albert Einstein is born in Ulm, Germany. The date later becomes Pi Day." },
  "04-12": { year: 1961, zh: "加加林乘坐东方一号飞船绕地球一周，成为第一个进入太空的人类。", en: "Yuri Gagarin aboard Vostok 1 becomes the first human in space, completing one orbit of Earth." },
  "04-15": { year: 1912, zh: "泰坦尼克号在首航途中撞上冰山后沉没，超过 1500 人遇难。", en: "The RMS Titanic sinks after striking an iceberg on its maiden voyage, killing more than 1,500 people." },
  "05-29": { year: 1953, zh: "希拉里与丹增诺尔盖首次成功登顶珠穆朗玛峰。", en: "Edmund Hillary and Tenzing Norgay become the first climbers confirmed to summit Mount Everest." },
  "06-06": { year: 1944, zh: "诺曼底登陆：盟军在法国北部海岸发起人类历史上最大规模的两栖作战。", en: "D-Day: Allied forces launch the largest seaborne invasion in history on the Normandy coast." },
  "06-28": { year: 1914, zh: "萨拉热窝事件：奥匈帝国皇储斐迪南大公遇刺，一个月后第一次世界大战爆发。", en: "Archduke Franz Ferdinand is assassinated in Sarajevo; within a month, the First World War begins." },
  "07-20": { year: 1969, zh: "阿波罗 11 号登月，阿姆斯特朗踏上月球表面：这是个人的一小步，却是人类的一大步。", en: "Apollo 11 lands on the Moon; Neil Armstrong takes 'one small step' onto the lunar surface." },
  "08-06": { year: 1991, zh: "蒂姆·伯纳斯-李发布第一个网站，万维网向公众打开。", en: "Tim Berners-Lee releases the first website, opening the World Wide Web to the public." },
  "08-15": { year: 1969, zh: "伍德斯托克音乐节开幕，三天里约 40 万人聚集在一座农场。", en: "The Woodstock music festival opens, drawing some 400,000 people to a farm in New York." },
  "09-02": { year: 1945, zh: "第二次世界大战正式结束，日本在密苏里号战列舰上签署投降书。", en: "The Second World War formally ends as Japan signs the surrender aboard USS Missouri." },
  "10-01": { year: 1949, zh: "中华人民共和国成立，开国大典在北京天安门广场举行。", en: "The People's Republic of China is founded, proclaimed at Tiananmen in Beijing." },
  "10-04": { year: 1957, zh: "苏联发射斯普特尼克 1 号，人类第一颗人造卫星进入轨道。", en: "The Soviet Union launches Sputnik 1, the first artificial satellite to orbit Earth." },
  "10-29": { year: 1969, zh: "ARPANET 完成第一次主机到主机的连接，互联网的雏形发出第一个词：login（只发出 lo 就崩溃了）。", en: "ARPANET makes its first host-to-host connection; the first message, 'login', crashes after just 'lo'." },
  "11-09": { year: 1989, zh: "柏林墙倒塌，冷战格局开始瓦解。", en: "The Berlin Wall falls, opening the way to German reunification and the end of the Cold War order." },
  "11-23": { year: 1963, zh: "《神秘博士》在 BBC 首播。这部剧后来成了世界上最长寿的科幻电视剧之一，今天仍在播出。", en: "Doctor Who premieres on the BBC. It goes on to become one of the longest-running science-fiction series in television history, and is still running today." },
  "12-17": { year: 1903, zh: "莱特兄弟在北卡罗来纳州完成人类第一次有动力、可控的飞行，只飞了 12 秒。", en: "The Wright brothers make the first powered, controlled aeroplane flight in North Carolina. It lasts 12 seconds." },
  "12-25": { year: 1642, zh: "牛顿出生于英格兰林肯郡伍尔索普（儒略历）。苹果和万有引力的故事，还要再等二十多年。", en: "Isaac Newton is born in Woolsthorpe, England (Julian calendar). The apple, and universal gravitation, are still two decades away." },
  "01-03": { year: 1959, zh: "阿拉斯加正式成为美国第 49 个州。", en: "Alaska is admitted as the 49th state of the United States." },
  "01-07": { year: 1610, zh: "伽利略用望远镜观测木星，第一次看到木星的卫星。人类眼中的宇宙，从此不一样了。", en: "Galileo observes Jupiter through a telescope and discovers its largest moons. The universe never looks the same again." },
  "01-12": { year: 2010, zh: "海地发生 7.0 级强震，首都太子港遭受重创，逾十万人遇难。", en: "A magnitude 7.0 earthquake devastates Haiti's capital, Port-au-Prince, killing well over 100,000 people." },
  "01-15": { year: 2001, zh: "维基百科上线。十五年后，它会成为人类历史上最大的百科全书，而它由志愿者写成。", en: "Wikipedia goes live. Written by volunteers, it will become the largest encyclopedia in human history." },
  "01-20": { year: 2009, zh: "奥巴马就任美国第 44 任总统，是美国历史上第一位非裔总统。", en: "Barack Obama is inaugurated as the 44th President of the United States, the first African American to hold the office." },
  "01-24": { year: 1848, zh: "加利福尼亚的萨特磨坊发现黄金，淘金热的大幕拉开，几十万人涌向西海岸。", en: "Gold is discovered at Sutter's Mill in California, setting off the Gold Rush that draws hundreds of thousands west." },
  "01-28": { year: 1986, zh: "挑战者号航天飞机在升空 73 秒后解体，七名宇航员遇难，全世界在电视直播中目睹了这一幕。", en: "The space shuttle Challenger breaks apart 73 seconds after launch, killing all seven crew members on live television." },
  "01-30": { year: 1948, zh: "圣雄甘地在德里遇刺身亡。印度独立运动的旗帜，倒在了独立不到半年的时刻。", en: "Mahatma Gandhi is assassinated in Delhi, less than six months after India won independence." },
  "02-04": { year: 2004, zh: "扎克伯格在哈佛宿舍里上线了 TheFacebook。它后来改名叫 Facebook。", en: "Mark Zuckerberg launches TheFacebook from a Harvard dorm room. It later drops the 'The'." },
  "02-07": { year: 1964, zh: "披头士首次抵达美国，降落在纽约肯尼迪机场，英伦入侵正式开始。", en: "The Beatles land at New York's Kennedy Airport for their first visit to the United States. The British Invasion begins." },
  "02-12": { year: 1809, zh: "达尔文出生于英格兰什鲁斯伯里。同一天，大洋彼岸的美国，林肯也出生了。", en: "Charles Darwin is born in Shrewsbury, England. Across the Atlantic, Abraham Lincoln is born on the same day." },
  "02-14": { year: 1876, zh: "贝尔在这一天提交了电话专利申请。几个小时后，格雷提交了类似的申请，电话的发明权之争打了很多年。", en: "Alexander Graham Bell files his telephone patent application, hours before Elisha Gray files a similar one. The dispute lasts for years." },
  "02-18": { year: 1930, zh: "汤博在洛厄尔天文台发现冥王星。它当了 76 年行星，2006 年被重新归类为矮行星。", en: "Clyde Tombaugh discovers Pluto at the Lowell Observatory. It remains a planet for 76 years before being reclassified as a dwarf planet in 2006." },
  "02-20": { year: 1962, zh: "约翰·格伦乘坐友谊 7 号绕地球三圈，成为第一个进入地球轨道的美国人。", en: "John Glenn, aboard Friendship 7, becomes the first American to orbit the Earth, circling it three times." },
  "02-23": { year: 1945, zh: "硫磺岛战役中，美国海军陆战队员在折钵山上升起星条旗，这一幕成为二战最著名的照片之一。", en: "U.S. Marines raise the American flag on Mount Suribachi during the Battle of Iwo Jima, creating one of the most famous photographs of the Second World War." },
  "02-28": { year: 1953, zh: "沃森与克里克在剑桥完成了 DNA 双螺旋结构的模型。生命的密码，从这一天起可以被画出来。", en: "Watson and Crick complete their model of DNA's double helix in Cambridge. The code of life can now be drawn." },
  "03-01": { year: 1872, zh: "黄石成为世界上第一个国家公园。把荒野圈起来保护，在当时是个全新的想法。", en: "Yellowstone becomes the world's first national park. Protecting wilderness by law is, at the time, a brand-new idea." },
  "03-05": { year: 1946, zh: "丘吉尔在美国密苏里州发表铁幕演说：从波罗的海到亚得里亚海，一幅铁幕已经降下。冷战的说法从此流行。", en: "Churchill delivers his 'Iron Curtain' speech in Missouri, popularising the phrase that will define the Cold War." },
  "03-10": { year: 1876, zh: "贝尔打出人类第一通电话，对助手沃森说了句：沃森先生，到这儿来，我需要你。", en: "Bell makes the first telephone call, summoning his assistant: 'Mr. Watson, come here, I want to see you.'" },
  "03-12": { year: 1930, zh: "甘地开始食盐进军，徒步近 400 公里到海边自制食盐，抗议英国的食盐专卖。非暴力不合作传遍世界。", en: "Gandhi begins the Salt March, walking some 390 kilometres to the sea to make salt in defiance of the British monopoly." },
  "03-15": { year: -44, zh: "罗马的 3 月 15 日，凯撒在元老院遇刺，身中 23 刀。莎士比亚后来让占卜者警告他：小心三月的望日。", en: "On the Ides of March, Julius Caesar is assassinated in Rome, stabbed 23 times. Shakespeare's soothsayer had warned him to beware the day." },
  "03-18": { year: 1965, zh: "苏联宇航员列昂诺夫完成人类第一次太空行走，在舱外漂浮了约 12 分钟。", en: "Soviet cosmonaut Alexei Leonov performs the first spacewalk, floating outside his capsule for about 12 minutes." },
  "03-23": { year: 1775, zh: "帕特里克·亨利发表演说：不自由，毋宁死。这句话成了美国独立运动最著名的口号。", en: "Patrick Henry delivers his 'Give me liberty, or give me death!' speech, a rallying cry of the American Revolution." },
  "03-25": { year: 1957, zh: "《罗马条约》签署，欧洲经济共同体成立。这是今天欧盟的起点。", en: "The Treaty of Rome is signed, creating the European Economic Community, the seed of today's European Union." },
  "03-31": { year: 1889, zh: "埃菲尔铁塔在巴黎落成揭幕。当时不少巴黎艺术家联名抗议，说它是个丑陋的怪物。", en: "The Eiffel Tower is inaugurated in Paris. Many Parisian artists had petitioned against it as an eyesore." },
  "04-01": { year: 1976, zh: "乔布斯、沃兹尼亚克和韦恩创立苹果公司。这一天是愚人节，但他们不是开玩笑。", en: "Steve Jobs, Steve Wozniak and Ronald Wayne found Apple Computer. It is April Fools' Day, but they are not joking." },
  "04-03": { year: 1973, zh: "摩托罗拉工程师马丁·库珀在纽约街头打出第一通手持移动电话，电话打给了竞争对手贝尔实验室。", en: "Motorola engineer Martin Cooper makes the first handheld mobile phone call on a New York street, to his rivals at Bell Labs." },
  "04-09": { year: 1865, zh: "南方军统帅罗伯特·李在阿波马托克斯向格兰特投降，美国内战实际上结束。", en: "Confederate general Robert E. Lee surrenders to Ulysses S. Grant at Appomattox, effectively ending the American Civil War." },
  "04-18": { year: 1906, zh: "旧金山发生大地震并引发大火，城市大半被毁，数千人遇难。", en: "A massive earthquake and ensuing fires devastate San Francisco, destroying much of the city and killing thousands." },
  "04-22": { year: 1970, zh: "第一个世界地球日，约 2000 万美国人走上街头。现代环保运动从这一天算起。", en: "The first Earth Day mobilises some 20 million Americans. The modern environmental movement dates itself from here." },
  "04-23": { year: 1616, zh: "莎士比亚逝世。按传统说法，这一天也是他的生日，他恰好活了 52 年。", en: "William Shakespeare dies. By tradition this is also his birthday, making him exactly 52 years old." },
  "04-26": { year: 1986, zh: "切尔诺贝利核电站 4 号机组爆炸，人类历史上最严重的核事故发生，辐射尘飘遍欧洲。", en: "Reactor 4 at Chernobyl explodes, causing the worst nuclear accident in history and spreading fallout across Europe." },
  "04-30": { year: 1789, zh: "华盛顿在纽约宣誓就任美国第一任总统。他是唯一一位获得全部选举人票的美国总统。", en: "George Washington is inaugurated in New York as the first President of the United States, the only one ever elected unanimously by the Electoral College." },
  "05-01": { year: 1931, zh: "帝国大厦在纽约落成开业。它当了 41 年世界最高建筑。", en: "The Empire State Building opens in New York. It remains the world's tallest building for 41 years." },
  "05-05": { year: 1961, zh: "艾伦·谢泼德乘坐自由 7 号完成 15 分钟的亚轨道飞行，成为第一个进入太空的美国人。", en: "Alan Shepard becomes the first American in space, on a 15-minute suborbital flight aboard Freedom 7." },
  "05-07": { year: 1945, zh: "德国在法国兰斯签署无条件投降书，次日生效。欧洲战场的第二次世界大战就此结束。", en: "Germany signs its unconditional surrender at Reims, effective the following day. The Second World War in Europe is over." },
  "05-10": { year: 1994, zh: "曼德拉就任南非总统。出狱四年后，他成了废除种族隔离的那个国家的领导人。", en: "Nelson Mandela is inaugurated as President of South Africa, four years after walking out of prison." },
  "05-14": { year: 1948, zh: "以色列国宣布成立。次日，第一次中东战争爆发。", en: "The State of Israel is proclaimed. The first Arab-Israeli war begins the next day." },
  "05-17": { year: 1954, zh: "美国最高法院在布朗诉教育委员会案中裁定，公立学校种族隔离违宪。隔离但平等从此在法律上站不住脚。", en: "In Brown v. Board of Education, the U.S. Supreme Court rules that racial segregation in public schools is unconstitutional." },
  "05-18": { year: 1980, zh: "圣海伦斯火山在美国华盛顿州大喷发，是美国本土有记录以来最具破坏力的火山喷发。", en: "Mount St. Helens erupts in Washington state, the most destructive volcanic eruption in recorded U.S. history." },
  "05-20": { year: 1927, zh: "林德伯格从纽约起飞，开始人类首次单人不间断飞越大西洋的航程，33 个半小时后降落在巴黎。", en: "Charles Lindbergh takes off from New York on the first solo nonstop transatlantic flight, landing in Paris 33 and a half hours later." },
  "05-25": { year: 1961, zh: "肯尼迪在国会宣布：美国要在十年内把人送上月球并安全返回。八年后，阿波罗 11 号做到了。", en: "Kennedy tells Congress that America should land a man on the Moon and return him safely before the decade is out. Apollo 11 does it eight years later." },
  "06-05": { year: 1981, zh: "美国疾控中心报告了一种罕见肺炎的聚集病例。这是艾滋病第一次出现在正式记录里，当时它还没有名字。", en: "The U.S. CDC reports a cluster of a rare pneumonia. It is the first official record of what will be called AIDS. It does not have a name yet." },
  "06-08": { year: 1949, zh: "奥威尔的小说《一九八四》出版。老大哥在看着你，从一句小说台词变成日常用语。", en: "George Orwell's novel Nineteen Eighty-Four is published. 'Big Brother is watching you' passes from fiction into everyday language." },
  "06-14": { year: 1777, zh: "大陆会议决议以星条旗为美国国旗。这一天后来成了美国的国旗日。", en: "The Continental Congress adopts the Stars and Stripes as the flag of the United States. The date is now Flag Day." },
  "06-16": { year: 1963, zh: "瓦莲京娜·捷列什科娃乘坐东方六号升空，成为第一个进入太空的女性。", en: "Valentina Tereshkova, aboard Vostok 6, becomes the first woman in space." },
  "06-18": { year: 1815, zh: "滑铁卢战役：拿破仑被威灵顿与布吕歇尔联军击败，他的时代就此终结。", en: "At the Battle of Waterloo, Napoleon is defeated by Wellington and Blücher. His era ends for good." },
  "06-22": { year: 1941, zh: "德国撕毁互不侵犯条约，巴巴罗萨行动开始，三百万德军进攻苏联。", en: "Germany tears up its non-aggression pact and launches Operation Barbarossa, invading the Soviet Union with three million troops." },
  "06-25": { year: 1950, zh: "朝鲜战争爆发。这场战争至今没有签署和平条约，只有停战协定。", en: "The Korean War begins. It has never been closed by a peace treaty, only an armistice." },
  "06-26": { year: 1945, zh: "《联合国宪章》在旧金山签署，联合国由此诞生。签字国 50 个。", en: "The United Nations Charter is signed in San Francisco by 50 nations, founding the UN." },
  "06-30": { year: 1908, zh: "通古斯大爆炸：一颗小行星在西伯利亚上空爆炸，夷平了两千多平方公里的森林。没有留下撞击坑，原因至今有争论。", en: "The Tunguska event: an asteroid explodes over Siberia, flattening more than 2,000 square kilometres of forest. It leaves no crater, and its exact nature is still debated." },
  "07-02": { year: 1964, zh: "美国总统约翰逊签署《民权法案》，在法律上禁止基于种族、肤色的歧视。", en: "President Johnson signs the Civil Rights Act, outlawing discrimination based on race, colour, religion, sex or national origin." },
  "07-04": { year: 1776, zh: "大陆会议通过《独立宣言》，十三个殖民地宣布脱离英国独立。这一天成了美国的国庆日。", en: "The Continental Congress adopts the Declaration of Independence. The date becomes America's Independence Day." },
  "07-06": { year: 1885, zh: "巴斯德的狂犬病疫苗第一次用在一个被疯狗咬伤的 9 岁男孩身上，孩子活了下来。疫苗时代的一次大胆一跃。", en: "Pasteur's rabies vaccine is used for the first time, on a 9-year-old boy bitten by a rabid dog. The boy survives." },
  "07-11": { year: 1804, zh: "美国副总统伯尔与前财政部长汉密尔顿决斗，汉密尔顿中枪，次日身亡。决斗在当时合法，后来被禁。", en: "Vice President Aaron Burr shoots former Treasury Secretary Alexander Hamilton in a duel. Hamilton dies the next day." },
  "07-14": { year: 1789, zh: "巴黎民众攻占巴士底狱。法国大革命的标志性一天，后来成了法国国庆日。", en: "Paris crowds storm the Bastille. The day becomes the emblem of the French Revolution, and France's national day." },
  "07-16": { year: 1945, zh: "三位一体核试验：人类第一颗原子弹在新墨西哥州的沙漠里试爆成功。奥本海默想起了薄伽梵歌里的那句话。", en: "The Trinity test: the first atomic bomb is detonated in the New Mexico desert. Oppenheimer recalls a line from the Bhagavad Gita." },
  "07-25": { year: 1978, zh: "世界上第一个试管婴儿路易丝·布朗在英国出生。辅助生殖技术从此走进普通人的生活。", en: "Louise Brown, the world's first baby conceived by IVF, is born in England." },
  "07-28": { year: 1914, zh: "奥匈帝国向塞尔维亚宣战，第一次世界大战正式开始。一个月前的一声枪响，滚成了四年大战。", en: "Austria-Hungary declares war on Serbia, formally beginning the First World War, a month after the Sarajevo assassination." },
  "08-01": { year: 1981, zh: "MTV 开播，第一支播放的音乐录影带叫《录影带杀死了广播明星》。预言得很准。", en: "MTV goes on air. The first music video it plays is 'Video Killed the Radio Star'. The prophecy proves accurate." },
  "08-04": { year: 1944, zh: "安妮·弗兰克一家在阿姆斯特丹的密室里被盖世太保发现。他们藏了整整两年零一个月。她的日记活了下来。", en: "Anne Frank and her family are discovered by the Gestapo in their Amsterdam hiding place, after two years in concealment. Her diary survives." },
  "08-09": { year: 1974, zh: "尼克松的辞职生效，他成为美国历史上唯一一位辞职的总统。水门事件画上句号。", en: "Richard Nixon's resignation takes effect. He remains the only U.S. president ever to resign the office." },
  "08-12": { year: 1981, zh: "IBM 发布个人电脑 IBM PC。个人电脑的时代，由一台开放架构的机器正式开启。", en: "IBM introduces the IBM PC. Its open architecture helps launch the personal computer era." },
  "08-21": { year: 1959, zh: "夏威夷成为美国第 50 个州，也是目前为止最后一个加入的州。", en: "Hawaii becomes the 50th U.S. state, the most recent to join the Union." },
  "08-24": { year: 79, zh: "维苏威火山喷发，庞贝与赫库兰尼姆被火山灰掩埋。一座罗马城市的时间，就此停在这一天。", en: "Mount Vesuvius erupts, burying Pompeii and Herculaneum. A Roman city's clock stops on this day." },
  "08-28": { year: 1963, zh: "马丁·路德·金在林肯纪念堂前发表我有一个梦想的演说，25 万人现场聆听。", en: "Martin Luther King Jr. delivers his 'I Have a Dream' speech before some 250,000 people at the Lincoln Memorial." },
  "08-31": { year: 1997, zh: "英国王妃戴安娜在巴黎车祸中去世，年仅 36 岁。消息震动了全世界。", en: "Diana, Princess of Wales, dies in a car crash in Paris, aged 36. The news shocks the world." },
  "09-01": { year: 1939, zh: "德国入侵波兰，第二次世界大战在欧洲爆发。英法两天后对德宣战。", en: "Germany invades Poland, beginning the Second World War in Europe. Britain and France declare war two days later." },
  "09-08": { year: 1966, zh: "《星际迷航》在 NBC 首播。最初收视率平平，后来成了流行文化史上影响最大的科幻系列之一。", en: "Star Trek premieres on NBC. Its early ratings are modest; it goes on to become one of the most influential science-fiction franchises ever." },
  "09-11": { year: 2001, zh: "九一一事件：恐怖分子劫持四架客机撞击世贸中心与五角大楼，近三千人遇难。这一天改变了此后二十多年的世界。", en: "The September 11 attacks: hijackers crash planes into the World Trade Center and the Pentagon, killing nearly 3,000 people and reshaping the decades that follow." },
  "09-12": { year: 1962, zh: "肯尼迪在莱斯大学发表演说：我们选择去月球，不是因为它容易，而是因为它难。", en: "Kennedy speaks at Rice University: 'We choose to go to the Moon, not because it is easy, but because it is hard.'" },
  "09-15": { year: 2008, zh: "雷曼兄弟申请破产，全球金融危机全面爆发。这是美国历史上最大的破产案。", en: "Lehman Brothers files for bankruptcy, the largest in U.S. history, and the global financial crisis erupts in full." },
  "09-17": { year: 1787, zh: "美国宪法在费城签署。它后来成为世界上现行最古老的成文宪法。", en: "The United States Constitution is signed in Philadelphia. It is now the oldest written national constitution still in use." },
  "09-21": { year: 1937, zh: "托尔金的《霍比特人》出版。比尔博的故事，是从一个写在空白页上的句子开始的。", en: "J. R. R. Tolkien's The Hobbit is published. It began as a single sentence scribbled on a blank exam page." },
  "09-26": { year: 1960, zh: "肯尼迪与尼克松举行美国历史上第一次电视直播总统辩论。看电视的人和听广播的人，对谁赢了判断完全不同。", en: "Kennedy and Nixon meet in the first televised U.S. presidential debate. Television viewers and radio listeners famously disagree about who won." },
  "09-27": { year: 1825, zh: "世界上第一条公共铁路斯托克顿至达灵顿铁路通车，蒸汽机车拉着客车跑完了全程。铁路时代开始。", en: "The Stockton and Darlington Railway opens, the world's first public railway to use steam locomotives. The railway age begins." },
  "10-02": { year: 1950, zh: "查尔斯·舒尔茨的《花生漫画》开始连载。查理·布朗和史努比的故事，一画就是五十年。", en: "Charles Schulz's Peanuts comic strip debuts. Charlie Brown and Snoopy will run for fifty years." },
  "10-08": { year: 1871, zh: "芝加哥大火燃起，连烧两天，城市三分之一被毁。起因传说是一头牛踢翻了油灯，多半是编的。", en: "The Great Chicago Fire begins, burning for two days and destroying a third of the city. The cow that supposedly started it is almost certainly a myth." },
  "10-14": { year: 1947, zh: "耶格尔驾驶 X-1 试验机突破音障，成为第一个实现超音速飞行的人。", en: "Chuck Yeager, flying the Bell X-1, becomes the first person to break the sound barrier in level flight." },
  "10-16": { year: 1962, zh: "肯尼迪得知苏联在古巴部署导弹，古巴导弹危机开始。接下来的 13 天，是冷战最接近核战争的时刻。", en: "Kennedy is shown evidence of Soviet missiles in Cuba. The Cuban Missile Crisis begins: thirteen days when the Cold War comes closest to nuclear war." },
  "10-19": { year: 1781, zh: "英军在约克镇向华盛顿投降，美国独立战争的大局就此底定。", en: "British forces surrender at Yorktown, effectively deciding the American Revolutionary War." },
  "10-21": { year: 1879, zh: "爱迪生测试成功第一只实用的白炽灯泡，连续点亮了 13 个半小时。", en: "Edison successfully tests the first practical incandescent light bulb. It burns for 13 and a half hours." },
  "10-24": { year: 1929, zh: "黑色星期四：纽约股市暴跌，大萧条的序幕。十年繁荣在一个秋天里结束。", en: "Black Thursday: the New York stock market crashes, opening the Great Depression. A decade of prosperity ends in one autumn." },
  "10-31": { year: 1517, zh: "马丁·路德在维滕贝格教堂门口贴出《九十五条论纲》，宗教改革的大幕拉开。", en: "Martin Luther posts his Ninety-five Theses on the church door at Wittenberg, opening the Protestant Reformation." },
  "11-04": { year: 2008, zh: "奥巴马赢得美国总统大选。从林肯签署解放宣言算起，走了 145 年。", en: "Barack Obama wins the U.S. presidential election, 145 years after Lincoln's Emancipation Proclamation." },
  "11-05": { year: 1605, zh: "火药阴谋被挫败：盖伊·福克斯等人在议会地窖里堆了 36 桶火药，准备炸死国王。此后英国每年这一天放焰火。", en: "The Gunpowder Plot is foiled: Guy Fawkes is found guarding 36 barrels of gunpowder beneath Parliament. Britain still marks the night with fireworks." },
  "11-11": { year: 1918, zh: "上午 11 点，一战停战协议生效。打了四年多的战争，在一个精心挑过的时刻停了下来。", en: "At 11 a.m., the Armistice ends the fighting of the First World War, on the eleventh day of the eleventh month." },
  "11-14": { year: 1969, zh: "阿波罗 12 号发射升空，人类第二次登月任务开始。它后来精确降落在预定地点附近。", en: "Apollo 12 launches, beginning the second crewed Moon landing, which touches down with pinpoint accuracy." },
  "11-17": { year: 1869, zh: "苏伊士运河通航，地中海与红海从此相连，欧洲到亚洲的航程缩短了约 7000 公里。", en: "The Suez Canal opens, joining the Mediterranean and the Red Sea and shortening the voyage from Europe to Asia by some 7,000 kilometres." },
  "11-19": { year: 1863, zh: "林肯发表葛底斯堡演说，全文只有 272 个词，讲了大约两分钟。摄影师甚至没来得及拍下他演讲的照片。", en: "Lincoln delivers the Gettysburg Address: 272 words, about two minutes. Photographers barely manage to capture it." },
  "11-22": { year: 1963, zh: "肯尼迪在达拉斯遇刺身亡。第二天，BBC 播出了一部新科幻剧的第一集，很多人忙着看新闻，没有注意到它。", en: "President Kennedy is assassinated in Dallas. The next day, the BBC airs the first episode of a new science-fiction series, largely unnoticed in the shadow of the news." },
  "11-24": { year: 1859, zh: "达尔文的《物种起源》出版，初版当天售罄。生物学从此有了统一的解释框架。", en: "Darwin's On the Origin of Species is published. The first edition sells out on the day." },
  "11-26": { year: 1922, zh: "卡特第一次探头看进图坦卡蒙陵墓的内室。被问到看见了什么，他说：是的，美妙的东西。", en: "Howard Carter first peers into the inner chamber of Tutankhamun's tomb. Asked if he can see anything, he replies: 'Yes, wonderful things.'" },
  "12-01": { year: 1955, zh: "罗莎·帕克斯在蒙哥马利的公交车上拒绝给白人让座，被逮捕。一场持续 381 天的公交抵制运动由此开始。", en: "Rosa Parks is arrested in Montgomery for refusing to give up her bus seat. A 381-day bus boycott follows." },
  "12-03": { year: 1967, zh: "巴纳德医生在南非完成人类第一次心脏移植手术。病人活了 18 天。", en: "Dr. Christiaan Barnard performs the first human heart transplant in South Africa. The patient lives for 18 days." },
  "12-07": { year: 1941, zh: "日本偷袭珍珠港，太平洋战争爆发。次日，美国对日宣战，全面卷入第二次世界大战。", en: "Japan attacks Pearl Harbor. The United States declares war the next day and enters the Second World War in full." },
  "12-09": { year: 1968, zh: "恩格尔巴特在旧金山做了一场演示：鼠标、超链接、视频会议、协同编辑，一次全亮了相。后来人们叫它所有演示之母。", en: "Douglas Engelbart gives a demonstration in San Francisco: the mouse, hyperlinks, video conferencing and collaborative editing, all at once. It is later called 'the Mother of All Demos.'" },
  "12-10": { year: 1901, zh: "第一届诺贝尔奖在斯德哥尔摩和克里斯蒂安尼亚（今奥斯陆）颁发，正是诺贝尔逝世五周年的日子。", en: "The first Nobel Prizes are awarded in Stockholm and Christiania (now Oslo), on the fifth anniversary of Alfred Nobel's death." },
  "12-14": { year: 1911, zh: "阿蒙森率领的挪威探险队抵达南极点，比斯科特早了 34 天。", en: "Roald Amundsen's Norwegian expedition reaches the South Pole, 34 days ahead of Scott." },
  "12-15": { year: 1791, zh: "美国宪法前十条修正案，即《权利法案》，获得批准生效。言论自由、宗教自由写进了第一条。", en: "The first ten amendments to the U.S. Constitution, the Bill of Rights, are ratified. Freedom of speech and religion stand in the first." },
  "12-27": { year: 1831, zh: "达尔文随小猎犬号从普利茅斯启航，开始五年环球航行。船上有个 22 岁的年轻人，还不知道自己会改写生物学。", en: "Darwin sets sail aboard HMS Beagle on a five-year voyage. The 22-year-old aboard has no idea he will rewrite biology." },
  "12-30": { year: 1922, zh: "苏维埃社会主义共和国联盟正式成立。它将在 69 年后的同一个月份解体。", en: "The Union of Soviet Socialist Republics is formally established. It will dissolve in the same month, 69 years later." },
  "01-02": { year: 1959, zh: "苏联发射月球1号探测器，它成为第一个飞掠月球的人造天体。", en: "The Soviet Union launches Luna 1, which becomes the first spacecraft to fly by the Moon." },
  "01-04": { year: 1809, zh: "路易·布莱叶出生于法国库夫赖，后来他发明了盲人使用的盲文。", en: "Louis Braille is born in Coupvray, France; he will go on to invent the braille reading system for the blind." },
  "01-05": { year: 1933, zh: "美国金门大桥在旧金山动工兴建，四年后通车。", en: "Construction of the Golden Gate Bridge begins in San Francisco; it will open four years later." },
  "01-06": { year: 1912, zh: "新墨西哥州正式加入美国，成为美国第47个州。", en: "New Mexico is admitted to the United States as its 47th state." },
  "01-08": { year: 1976, zh: "中国国务院总理周恩来在北京逝世，享年78岁。", en: "Zhou Enlai, premier of China, dies in Beijing at the age of 78." },
  "01-09": { year: 2007, zh: "史蒂夫·乔布斯在旧金山发布第一代iPhone，重新定义了智能手机。", en: "Steve Jobs introduces the first iPhone in San Francisco, redefining the smartphone." },
  "01-10": { year: 1863, zh: "伦敦地铁大都会线通车，这是世界上第一条城市地下铁路。", en: "The Metropolitan Railway opens in London, becoming the world's first urban underground railway." },
  "01-11": { year: 1922, zh: "胰岛素在加拿大多伦多首次成功用于治疗糖尿病患者。", en: "Insulin is used for the first time to successfully treat a diabetes patient, in Toronto, Canada." },
  "01-13": { year: 1898, zh: "法国作家左拉发表公开信《我控诉……！》，为德雷福斯案鸣冤。", en: "French writer Émile Zola publishes his open letter \"J'accuse...!\", defending Alfred Dreyfus." },
  "01-14": { year: 1875, zh: "阿尔伯特·史怀哲出生于阿尔萨斯，他后来在非洲行医并获得诺贝尔和平奖。", en: "Albert Schweitzer is born in Alsace; he will later practice medicine in Africa and win the Nobel Peace Prize." },
  "01-16": { year: 1969, zh: "苏联联盟4号与联盟5号飞船在太空对接，完成首次载人飞船交会对接与乘员转移。", en: "The Soviet Soyuz 4 and Soyuz 5 dock in orbit, completing the first docking of two crewed spacecraft and the first crew transfer." },
  "01-17": { year: 1706, zh: "本杰明·富兰克林出生于波士顿，后来他既是科学家，也是美国的开国元勋之一。", en: "Benjamin Franklin is born in Boston; he will become both a scientist and a Founding Father of the United States." },
  "01-18": { year: 1778, zh: "英国航海家詹姆斯·库克抵达夏威夷群岛，成为首批到访的欧洲人之一。", en: "British explorer James Cook reaches the Hawaiian Islands, among the first Europeans to visit them." },
  "01-19": { year: 1809, zh: "美国作家埃德加·爱伦·坡出生于波士顿，以《乌鸦》等作品闻名。", en: "American writer Edgar Allan Poe is born in Boston, later famous for works such as \"The Raven\"." },
  "01-21": { year: 1793, zh: "法国国王路易十六在巴黎被送上断头台，法国大革命走向激化。", en: "King Louis XVI of France is guillotined in Paris as the French Revolution intensifies." },
  "01-22": { year: 1901, zh: "英国维多利亚女王逝世，在位63年多的维多利亚时代就此落幕。", en: "Queen Victoria of Britain dies, ending the Victorian era after a reign of more than 63 years." },
  "01-23": { year: 1849, zh: "伊丽莎白·布莱克韦尔在纽约毕业，成为美国第一位获得医学学位的女性。", en: "Elizabeth Blackwell graduates in New York, becoming the first woman to earn a medical degree in the United States." },
  "01-25": { year: 1915, zh: "贝尔与沃森完成首次横贯美国大陆的电话通话，从纽约打到旧金山。", en: "Alexander Graham Bell and Thomas Watson complete the first transcontinental telephone call, from New York to San Francisco." },
  "01-26": { year: 1788, zh: "英国第一舰队抵达悉尼湾，在澳大利亚建立起第一个欧洲殖民地。", en: "Britain's First Fleet arrives at Sydney Cove, establishing the first European colony in Australia." },
  "01-29": { year: 1886, zh: "卡尔·本茨为他的三轮汽车申请专利，这被视为世界上第一辆实用的汽车。", en: "Karl Benz patents his three-wheeled Motorwagen, regarded as the world's first practical automobile." },
  "01-31": { year: 1958, zh: "美国在佛罗里达发射探索者1号，这是美国成功发射的第一颗人造卫星。", en: "The United States launches Explorer 1 from Florida, its first successful artificial satellite." },
  "02-01": { year: 1884, zh: "《牛津英语词典》第一分册出版，这部巨著的编纂历时数十年。", en: "The first fascicle of the Oxford English Dictionary is published; the vast work will take decades to complete." },
  "02-02": { year: 1925, zh: "狗拉雪橇接力把白喉抗毒素送达阿拉斯加诺姆，最后一程的领头犬是巴尔托。", en: "A dog-sled relay delivers diphtheria antitoxin to Nome, Alaska, with Balto leading the final team into town." },
  "02-03": { year: 1966, zh: "苏联月球9号探测器在月球表面软着陆，实现人类探测器首次月面软着陆。", en: "The Soviet Luna 9 probe soft-lands on the Moon, achieving the first soft landing on the lunar surface." },
  "02-05": { year: 1971, zh: "阿波罗14号登月舱降落在月球弗拉·毛罗高地，谢泼德与米切尔踏上月面。", en: "Apollo 14 lands in the Moon's Fra Mauro highlands, and Alan Shepard and Edgar Mitchell walk on the lunar surface." },
  "02-06": { year: 1952, zh: "英国国王乔治六世逝世，其女伊丽莎白二世即位，开启长达70年的统治。", en: "King George VI of Britain dies and his daughter Elizabeth II succeeds him, beginning a reign of 70 years." },
  "02-08": { year: 1828, zh: "法国作家儒勒·凡尔纳出生于南特，后来写出《海底两万里》等科幻名作。", en: "French writer Jules Verne is born in Nantes; he will write science-fiction classics such as Twenty Thousand Leagues Under the Seas." },
  "02-09": { year: 1964, zh: "披头士乐队首次登上美国《埃德·沙利文秀》，引发全美热潮。", en: "The Beatles make their first appearance on America's Ed Sullivan Show, sparking a nationwide sensation." },
  "02-10": { year: 1996, zh: "IBM超级计算机“深蓝”首次在一局国际象棋中击败世界冠军卡斯帕罗夫。", en: "IBM's Deep Blue supercomputer defeats world champion Garry Kasparov in a game of chess for the first time." },
  "02-13": { year: 1891, zh: "美国画家格兰特·伍德出生于艾奥瓦州，后来画出名作《美国哥特式》。", en: "American painter Grant Wood is born in Iowa; he will later paint the iconic American Gothic." },
  "02-15": { year: 1564, zh: "伽利略·伽利莱出生于意大利比萨，后来成为近代科学革命的关键人物。", en: "Galileo Galilei is born in Pisa, Italy; he will become a central figure of the Scientific Revolution." },
  "02-16": { year: 1923, zh: "霍华德·卡特打开埃及法老图坦卡蒙的墓室，露出满室珍宝。", en: "Howard Carter opens the burial chamber of Pharaoh Tutankhamun in Egypt, revealing its treasures." },
  "02-17": { year: 1972, zh: "大众甲壳虫第15007034辆下线，超越福特T型车成为当时产量最高的汽车。", en: "The 15,007,034th Volkswagen Beetle is built, surpassing the Ford Model T as the most-produced car of its time." },
  "02-19": { year: 1997, zh: "邓小平在北京逝世，享年92岁，他是中国改革开放的总设计师。", en: "Deng Xiaoping dies in Beijing at the age of 92; he was the chief architect of China's reform and opening up." },
  "02-21": { year: 1972, zh: "美国总统尼克松抵达北京，开启对中国的历史性访问，中美关系开始解冻。", en: "U.S. President Richard Nixon arrives in Beijing for a historic visit to China, beginning a thaw in U.S.–China relations." },
  "02-22": { year: 1732, zh: "乔治·华盛顿出生于弗吉尼亚，后来成为美国第一任总统。", en: "George Washington is born in Virginia; he will become the first president of the United States." },
  "02-24": { year: 1582, zh: "教皇格里高利十三世颁布诏书推行格里历，即今天世界通用的公历。", en: "Pope Gregory XIII issues the bull introducing the Gregorian calendar, now the world's standard civil calendar." },
  "02-25": { year: 1870, zh: "海勒姆·雷维尔斯宣誓就任美国参议员，成为美国国会首位非裔议员。", en: "Hiram Revels is sworn in as a U.S. senator, becoming the first African American to serve in the U.S. Congress." },
  "02-26": { year: 1815, zh: "拿破仑逃离厄尔巴岛流放地返回法国，开始他短暂的“百日王朝”。", en: "Napoleon escapes exile on Elba and returns to France, beginning his short-lived Hundred Days." },
  "02-27": { year: 1996, zh: "《宝可梦 红·绿》在日本发售，一个风靡全球的游戏系列就此诞生。", en: "Pokémon Red and Green are released in Japan, launching a video-game series that will become a global phenomenon." },
  "02-29": { year: 1940, zh: "哈蒂·麦克丹尼尔凭《乱世佳人》获得奥斯卡最佳女配角奖，成为首位获得奥斯卡奖的非裔演员。", en: "Hattie McDaniel wins the Academy Award for Best Supporting Actress for Gone with the Wind, becoming the first African American to win an Oscar." },
  "03-02": { year: 1969, zh: "协和式超音速客机在法国图卢兹完成首飞，开启了民航的超音速时代。", en: "The Concorde supersonic airliner makes its maiden flight from Toulouse, France, ushering in the age of supersonic passenger travel." },
  "03-03": { year: 1875, zh: "第一场有记载的室内冰球比赛在蒙特利尔维多利亚滑冰场举行，由麦吉尔大学学生组织。", en: "The first recorded indoor ice hockey game is played at the Victoria Skating Rink in Montreal, organized by McGill University students." },
  "03-04": { year: 1877, zh: "柴可夫斯基的芭蕾舞剧《天鹅湖》在莫斯科大剧院首演，日后成为最受欢迎的芭蕾经典。", en: "Tchaikovsky's ballet Swan Lake premieres at the Bolshoi Theatre in Moscow; it will become one of the most beloved ballets of all time." },
  "03-06": { year: 1475, zh: "米开朗基罗出生于意大利卡普雷塞，这位文艺复兴巨匠日后画出了西斯廷教堂天顶画、雕出了《大卫》。", en: "Michelangelo is born in Caprese, Italy; the Renaissance master will paint the Sistine Chapel ceiling and sculpt David." },
  "03-07": { year: 1876, zh: "亚历山大·格雷厄姆·贝尔获得电话专利，三天后他对助手说出了那句著名的「华生先生，请过来」。", en: "Alexander Graham Bell is granted a patent for the telephone; three days later he speaks its famous first words to his assistant Watson." },
  "03-08": { year: 1910, zh: "法国飞行员雷蒙德·德拉罗什成为世界上第一位获得飞行执照的女性。", en: "French aviator Raymonde de Laroche becomes the first woman in the world to receive a pilot's licence." },
  "03-09": { year: 1776, zh: "亚当·斯密的《国富论》在伦敦出版，奠定了现代经济学的基础。", en: "Adam Smith publishes The Wealth of Nations in London, laying the foundations of modern economics." },
  "03-11": { year: 1990, zh: "立陶宛宣布恢复独立，成为第一个脱离苏联的加盟共和国。", en: "Lithuania declares the restoration of its independence, becoming the first Soviet republic to break away from the USSR." },
  "03-13": { year: 1781, zh: "天文学家威廉·赫歇尔在巴斯自家花园里观测到天王星，这是第一颗用望远镜发现的行星。", en: "Astronomer William Herschel observes Uranus from his garden in Bath, the first planet discovered with a telescope." },
  "03-16": { year: 1926, zh: "罗伯特·戈达德在马萨诸塞州发射了世界第一枚液体燃料火箭，只飞了2.5秒，却开启了航天时代。", en: "Robert Goddard launches the world's first liquid-fuelled rocket in Massachusetts; it flies for just 2.5 seconds but opens the space age." },
  "03-17": { year: 1861, zh: "意大利王国宣告成立，维托里奥·埃马努埃莱二世成为统一意大利的第一位国王。", en: "The Kingdom of Italy is proclaimed, with Victor Emmanuel II as the first king of a united Italy." },
  "03-19": { year: 1279, zh: "崖山海战中元军击败宋军，陆秀夫背负幼帝赵昺投海，南宋灭亡。", en: "At the Battle of Yamen, Mongol forces defeat the Song; the minister Lu Xiufu leaps into the sea with the child emperor, ending the Song dynasty." },
  "03-20": { year: 1852, zh: "斯托夫人的小说《汤姆叔叔的小屋》出版，成为19世纪最畅销的小说之一，推动了废奴运动。", en: "Harriet Beecher Stowe's Uncle Tom's Cabin is published; it becomes one of the century's best-selling novels and fuels the abolitionist movement." },
  "03-21": { year: 1804, zh: "《拿破仑法典》在法国颁行，这部民法典深刻影响了此后世界许多国家的法律体系。", en: "The Napoleonic Code takes effect as France's civil law; it will profoundly shape legal systems around the world." },
  "03-22": { year: 1963, zh: "披头士乐队发行首张专辑《Please Please Me》，「披头士狂热」即将席卷全球。", en: "The Beatles release their debut album Please Please Me, just before Beatlemania sweeps the world." },
  "03-24": { year: 1882, zh: "德国科学家罗伯特·科赫宣布发现结核杆菌，找到了肺结核的病因。", en: "German scientist Robert Koch announces his discovery of the bacterium that causes tuberculosis." },
  "03-26": { year: 1953, zh: "乔纳斯·索尔克宣布研制成功脊髓灰质炎（小儿麻痹症）疫苗，为消灭这种疾病带来希望。", en: "Jonas Salk announces a successful vaccine against polio, raising hopes of eradicating the crippling disease." },
  "03-27": { year: 1998, zh: "美国食品药品管理局批准「伟哥」（万艾可）上市，它很快成为全球热议的现象级药物。", en: "The US Food and Drug Administration approves Viagra, which quickly becomes a worldwide cultural phenomenon." },
  "03-28": { year: 1979, zh: "美国宾夕法尼亚州三里岛核电站发生堆芯部分熔毁事故，是美国历史上最严重的核事故。", en: "A partial reactor meltdown occurs at the Three Mile Island nuclear plant in Pennsylvania, the worst nuclear accident in US history." },
  "03-29": { year: 1974, zh: "陕西临潼的农民打井时挖出陶俑碎片，沉睡两千多年的秦始皇兵马俑就此重见天日。", en: "Farmers digging a well near Xi'an unearth terracotta fragments, revealing the Terracotta Army buried with China's first emperor for over 2,000 years." },
  "03-30": { year: 1867, zh: "美国与俄国签署条约，以720万美元买下阿拉斯加，当时不少人嘲笑这是「西沃德的蠢事」。", en: "The United States signs a treaty to buy Alaska from Russia for $7.2 million, a deal mocked at the time as 'Seward's Folly'." },
  "04-02": { year: 1805, zh: "童话作家安徒生出生于丹麦欧登塞，他写下的《丑小鸭》《卖火柴的小女孩》陪伴了全世界的孩子。", en: "Fairy-tale author Hans Christian Andersen is born in Odense, Denmark; his tales like The Ugly Duckling will enchant children worldwide." },
  "04-04": { year: 1949, zh: "美、英、法等12国在华盛顿签署《北大西洋公约》，北约正式成立。", en: "Twelve nations sign the North Atlantic Treaty in Washington, founding NATO." },
  "04-05": { year: 1722, zh: "荷兰航海家罗赫芬在复活节这天抵达一座南太平洋小岛，将其命名为「复活节岛」。", en: "Dutch explorer Jacob Roggeveen reaches a small Pacific island on Easter Sunday and names it Easter Island." },
  "04-06": { year: 1896, zh: "第一届现代奥运会在希腊雅典开幕，13个国家的241名运动员参加了比赛。", en: "The first modern Olympic Games open in Athens, Greece, with 241 athletes from 13 nations." },
  "04-07": { year: 1948, zh: "世界卫生组织正式成立，这一天后来被定为世界卫生日。", en: "The World Health Organization is formally established; the date is later observed as World Health Day." },
  "04-08": { year: 1973, zh: "西班牙画家巴勃罗·毕加索在法国穆然逝世，享年91岁，身后留下数以万计的作品。", en: "Spanish artist Pablo Picasso dies at Mougins, France, aged 91, leaving behind tens of thousands of works." },
  "04-10": { year: 1912, zh: "号称「永不沉没」的泰坦尼克号从英国南安普顿启程首航，驶向纽约。", en: "The supposedly unsinkable Titanic sets sail from Southampton on her maiden voyage to New York." },
  "04-11": { year: 1970, zh: "阿波罗13号载着三名宇航员发射升空，两天后飞船氧气罐爆炸，上演了航天史上最惊险的返航。", en: "Apollo 13 launches with three astronauts aboard; an oxygen tank explosion two days later sets up the most perilous return in spaceflight history." },
  "04-13": { year: 1742, zh: "亨德尔的清唱剧《弥赛亚》在都柏林首演，其中「哈利路亚」大合唱后来成为经典。", en: "Handel's oratorio Messiah premieres in Dublin; its 'Hallelujah' chorus will become a beloved classic." },
  "04-14": { year: 2003, zh: "人类基因组计划宣布完成，测出了人类DNA约30亿个碱基对的序列。", en: "The Human Genome Project is declared complete, having sequenced the roughly three billion base pairs of human DNA." },
  "04-16": { year: 1889, zh: "查理·卓别林出生于伦敦，他拄着拐杖、戴着圆顶礼帽的小流浪汉形象将成为电影的永恒符号。", en: "Charlie Chaplin is born in London; his bowler-hatted Little Tramp will become cinema's most enduring character." },
  "04-17": { year: 1970, zh: "在太空历险四天后，阿波罗13号三名宇航员安全溅落太平洋，被誉为「成功的失败」。", en: "After four harrowing days in space, the Apollo 13 astronauts splash down safely in the Pacific — a 'successful failure'." },
  "04-19": { year: 1775, zh: "莱克星顿与康科德战役打响，「莱克星顿的枪声」揭开了美国独立战争的序幕。", en: "The Battles of Lexington and Concord are fought — the 'shot heard round the world' opens the American Revolutionary War." },
  "04-20": { year: 2010, zh: "墨西哥湾「深水地平线」钻井平台爆炸起火，造成美国历史上最严重的海上漏油事故。", en: "The Deepwater Horizon drilling rig explodes in the Gulf of Mexico, causing the largest marine oil spill in US history." },
  "04-21": { year: 1960, zh: "巴西新首都巴西利亚正式落成，这座从无到有建起的现代主义城市只用了不到四年。", en: "Brasília is inaugurated as Brazil's new capital, a modernist city built from scratch in under four years." },
  "04-24": { year: 1990, zh: "哈勃太空望远镜随「发现号」航天飞机发射升空，从此彻底改变了人类看宇宙的方式。", en: "The Hubble Space Telescope is launched aboard the shuttle Discovery; it will transform humanity's view of the universe." },
  "04-25": { year: 1953, zh: "沃森与克里克在《自然》杂志发表论文，提出DNA的双螺旋结构模型。", en: "Watson and Crick publish their paper in Nature proposing the double-helix structure of DNA." },
  "04-27": { year: 1521, zh: "航海家麦哲伦在菲律宾马克坦岛的战斗中身亡，他的船队后来完成了人类首次环球航行。", en: "Explorer Ferdinand Magellan is killed at the Battle of Mactan in the Philippines; his expedition will go on to complete the first circumnavigation of the globe." },
  "04-28": { year: 2001, zh: "美国富商丹尼斯·蒂托搭乘俄国飞船前往国际空间站，成为世界第一位太空游客。", en: "American businessman Dennis Tito flies to the International Space Station aboard a Russian spacecraft, becoming the world's first space tourist." },
  "04-29": { year: 2011, zh: "英国威廉王子与凯特·米德尔顿在伦敦威斯敏斯特教堂举行婚礼，全球数亿人观看了直播。", en: "Prince William marries Catherine Middleton at Westminster Abbey in London, watched live by hundreds of millions worldwide." },
  "05-02": { year: 1519, zh: "达·芬奇在法国昂布瓦斯逝世，这位画家同时是解剖学家、工程师和发明家。", en: "Leonardo da Vinci dies at Amboise in France, a painter who was also an anatomist, engineer and inventor." },
  "05-03": { year: 1947, zh: "日本国宪法正式施行，日本战后的新秩序自此有了根本法。", en: "The postwar Constitution of Japan comes into effect, giving the country a new fundamental law." },
  "05-04": { year: 1919, zh: "北京学生走上街头，抗议巴黎和会将山东权益转让给日本，五四运动爆发。", en: "Students in Beijing protest the Paris Peace Conference decision to transfer Shandong rights to Japan, sparking the May Fourth Movement." },
  "05-06": { year: 1954, zh: "英国人罗杰·班尼斯特在牛津跑出一英里3分59秒4，成为首位一英里跑进四分钟的人。", en: "Roger Bannister runs the mile in 3 minutes 59.4 seconds at Oxford, the first person to break the four-minute barrier." },
  "05-08": { year: 1945, zh: "德国无条件投降生效，欧洲战场的战事结束，这一天成为欧洲胜利日。", en: "Germany's unconditional surrender takes effect and the war in Europe ends, a date marked as Victory in Europe Day." },
  "05-09": { year: 1950, zh: "法国外长舒曼提出将法德两国的煤钢生产置于共同管理之下，这一宣言被视为欧洲联盟的起点。", en: "French foreign minister Robert Schuman proposes pooling French and German coal and steel production, a declaration seen as the starting point of the European Union." },
  "05-11": { year: 1997, zh: "IBM的“深蓝”计算机在决胜局击败国际象棋世界冠军卡斯帕罗夫，赢下这场六局制的人机对抗赛。", en: "IBM's Deep Blue defeats world chess champion Garry Kasparov in the deciding game to win their six-game match." },
  "05-12": { year: 1820, zh: "弗洛伦斯·南丁格尔出生于佛罗伦萨，日后她将创立现代护理学，她的生日后来成为国际护士节。", en: "Florence Nightingale is born in Florence; she will go on to found modern nursing, and her birthday is now marked as International Nurses Day." },
  "05-13": { year: 1940, zh: "丘吉尔首次以首相身份在下议院发表演说，称自己能奉献的只有热血、辛劳、眼泪和汗水。", en: "Winston Churchill addresses the House of Commons for the first time as prime minister, offering nothing but 'blood, toil, tears and sweat'." },
  "05-15": { year: 1928, zh: "米奇和米妮在无声短片《飞机狂》的试映中首次登上银幕，正式走红还要等到几个月后的《汽船威利号》。", en: "Mickey and Minnie Mouse appear on screen for the first time in a test screening of the silent short Plane Crazy, months before Steamboat Willie makes them famous." },
  "05-16": { year: 1929, zh: "第一届奥斯卡金像奖在好莱坞举行，宴会只有约270位宾客，获奖名单早已提前公布。", en: "The first Academy Awards are held in Hollywood before some 270 guests, with the winners already announced in advance." },
  "05-19": { year: 1962, zh: "玛丽莲·梦露在麦迪逊广场花园的庆生晚会上，为肯尼迪总统唱起那首著名的《生日快乐，总统先生》。", en: "Marilyn Monroe sings 'Happy Birthday, Mr. President' to John F. Kennedy at a birthday gala in Madison Square Garden." },
  "05-21": { year: 1927, zh: "林德伯格驾驶单引擎飞机抵达巴黎，完成史上首次单人不间断跨大西洋飞行。", en: "Charles Lindbergh lands in Paris, completing the first solo nonstop transatlantic flight." },
  "05-22": { year: 1980, zh: "南梦宫的街机游戏《吃豆人》在日本问世，那个缺了一角的黄色圆形象此后风靡全球。", en: "Namco's arcade game Pac-Man is released in Japan, and the yellow circle with a missing wedge goes on to conquer the world." },
  "05-23": { year: 1949, zh: "德意志联邦共和国《基本法》颁布，联邦德国正式成立。", en: "The Basic Law of the Federal Republic of Germany is promulgated, formally establishing West Germany." },
  "05-24": { year: 1844, zh: "莫尔斯从华盛顿向巴尔的摩发出第一封长途电报，内容是《圣经》中的一句话：上帝创造了何等奇迹。", en: "Samuel Morse sends the first long-distance telegraph message from Washington to Baltimore: 'What hath God wrought'." },
  "05-26": { year: 1967, zh: "披头士的专辑《佩珀军士的孤独之心俱乐部乐队》在英国发行，被视为把专辑当作完整艺术作品的里程碑。", en: "The Beatles' album Sgt. Pepper's Lonely Hearts Club Band is released in Britain, a landmark in treating the album as a unified work of art." },
  "05-27": { year: 1937, zh: "金门大桥向行人开放，约20万人步行过桥，次日才开始通车。", en: "The Golden Gate Bridge opens to pedestrians, and some 200,000 people walk across before vehicles are allowed the next day." },
  "05-28": { year: 1959, zh: "两只猴子艾布尔和贝克乘火箭升空并平安返回，成为最早活着完成太空飞行的猴子。", en: "Monkeys Able and Baker become the first monkeys to survive a spaceflight, returning safely from a 16-minute ride aboard a Jupiter rocket." },
  "05-30": { year: 1922, zh: "华盛顿的林肯纪念堂举行落成典礼，36根大理石柱象征林肯时代美国的36个州。", en: "The Lincoln Memorial is dedicated in Washington, its 36 marble columns representing the 36 states of Lincoln's America." },
  "05-31": { year: 1911, zh: "泰坦尼克号在贝尔法斯特下水，当时它是世界上最大的船舶，而它的处女航还要等上近一年。", en: "Titanic is launched at Belfast, then the largest ship in the world; her maiden voyage is still almost a year away." },
  "06-01": { year: 1980, zh: "美国有线电视新闻网CNN开播，成为世界上第一个24小时电视新闻频道。", en: "CNN goes on air in the United States as the world's first 24-hour television news channel." },
  "06-02": { year: 1953, zh: "伊丽莎白二世在伦敦西敏寺加冕，这是英国首次全程电视转播的加冕礼。", en: "Elizabeth II is crowned at Westminster Abbey in London, in the first British coronation televised in full." },
  "06-03": { year: 1965, zh: "美国宇航员爱德华·怀特走出双子星4号飞船，完成美国历史上的首次太空行走。", en: "Astronaut Edward White steps out of Gemini 4 to perform the first American spacewalk." },
  "06-04": { year: 1919, zh: "美国参议院通过宪法第十九修正案，美国妇女的选举权向成为宪法权利迈出关键一步。", en: "The United States Senate passes the Nineteenth Amendment, a decisive step toward a constitutional right to vote for American women." },
  "06-07": { year: 1954, zh: "计算机科学先驱艾伦·图灵逝世，年仅41岁，他留下的图灵机与图灵测试至今仍在被讨论。", en: "Alan Turing, a founding figure of computer science, dies aged 41, leaving behind the Turing machine and the Turing test." },
  "06-09": { year: 1934, zh: "唐老鸭在动画短片《聪明的小母鸡》中首次登场，它的坏脾气和鸭子嗓一样让人难忘。", en: "Donald Duck makes his debut in the cartoon The Wise Little Hen, with a temper as memorable as his voice." },
  "06-10": { year: 1829, zh: "首届牛津剑桥赛艇对抗赛在泰晤士河亨利段举行，牛津队获胜，这项延续至今的年度对抗由此开场。", en: "Oxford beat Cambridge in the first University Boat Race, rowed at Henley-on-Thames, starting a rivalry that continues today." },
  "06-11": { year: 1982, zh: "斯皮尔伯格的电影《E.T. 外星人》在美国上映，那个一心想回家的小外星人成为一代人的童年记忆。", en: "Steven Spielberg's film E.T. the Extra-Terrestrial opens in the United States, and its homesick alien becomes a childhood memory for a generation." },
  "06-12": { year: 1942, zh: "安妮·弗兰克在13岁生日这天收到一本日记本并开始写日记，这本日记后来举世闻名。", en: "Anne Frank receives a diary for her thirteenth birthday and begins writing in it, the start of the diary that will become world-famous." },
  "06-13": { year: 1983, zh: "先驱者10号飞越海王星轨道，成为第一个离开太阳系主要行星区域、飞向群星的人造物体。", en: "Pioneer 10 crosses the orbit of Neptune, becoming the first human-made object to leave the realm of the major planets, bound for the stars." },
  "06-15": { year: 1215, zh: "英格兰国王约翰在兰尼米德在大宪章上用印，王室的权力第一次被白纸黑字限制。", en: "King John of England seals Magna Carta at Runnymede, putting royal power under written limits for the first time." },
  "06-17": { year: 1885, zh: "拆成200多箱的自由女神像乘法国军舰抵达纽约，组装和揭幕还要等上一年多。", en: "The Statue of Liberty arrives in New York aboard a French ship, packed in more than 200 crates; assembly and unveiling will take over a year." },
  "06-19": { year: 1865, zh: "奴隶获得解放的消息终于传到得克萨斯州的加尔维斯顿，这一天后来成为美国的六月节。", en: "News of emancipation finally reaches enslaved people in Galveston, Texas, a date now commemorated in the United States as Juneteenth." },
  "06-20": { year: 1975, zh: "电影《大白鲨》在美国上映，开创了暑期大片的时代，也让许多人那年夏天不敢下海。", en: "Jaws opens in the United States, launching the era of the summer blockbuster and keeping many swimmers out of the sea that year." },
  "06-21": { year: 1948, zh: "曼彻斯特的“Baby”计算机运行了它的第一个存储程序，这台婴儿机迈出了通向现代计算机的第一步。", en: "The Manchester Baby runs its first stored program, a first step toward the modern computer." },
  "06-23": { year: 1972, zh: "美国《教育修正案》第九条签署成为法律，禁止公立教育中的性别歧视，深刻改变了校园体育。", en: "Title IX is signed into law in the United States, banning sex discrimination in federally funded education and transforming school and college sports." },
  "06-24": { year: 1812, zh: "拿破仑率大军渡过涅曼河入侵俄国，这场曾横扫欧洲的远征将在俄国的严冬中走向崩溃。", en: "Napoleon leads his Grande Armée across the Neman River into Russia, beginning an invasion that the Russian winter will destroy." },
  "06-27": { year: 1954, zh: "苏联奥布宁斯克核电站并网发电，这是世界上第一座接入电网的核电站，功率虽小，意义却大。", en: "The Obninsk nuclear power plant in the Soviet Union is connected to the power grid, the first nuclear plant in the world to supply electricity to a grid." },
  "06-29": { year: 1613, zh: "莎士比亚的环球剧场在演出《亨利八世》时被一门道具炮引燃茅草屋顶而烧毁，所幸无人丧生，只有一位观众用啤酒浇灭了着火的裤子。", en: "Shakespeare's Globe Theatre burns down during Henry VIII when a stage cannon sets the thatched roof alight; no one is killed, though one man douses his burning breeches with ale." },
  "07-01": { year: 1997, zh: "英国将香港主权移交中国，156 年的殖民统治结束，“一国两制”就此开启。", en: "Britain hands Hong Kong back to China, ending 156 years of colonial rule and beginning 'one country, two systems'." },
  "07-03": { year: 1608, zh: "法国探险家尚普兰在圣劳伦斯河畔创建魁北克城，成为北美最古老的城市之一。", en: "French explorer Samuel de Champlain founds Quebec City on the St. Lawrence River, one of North America's oldest cities." },
  "07-05": { year: 1687, zh: "牛顿发表《自然哲学的数学原理》，万有引力和三大运动定律就此奠定近代物理学。", en: "Newton publishes Principia Mathematica, laying out universal gravitation and the laws of motion that found modern physics." },
  "07-07": { year: 1937, zh: "卢沟桥事变爆发，中国全民族抗日战争全面开始。", en: "The Marco Polo Bridge Incident erupts near Beijing, beginning China's full-scale War of Resistance against Japan." },
  "07-08": { year: 1497, zh: "达·伽马率船队从里斯本启航，绕过好望角，开辟了欧洲通往印度的海路。", en: "Vasco da Gama sets sail from Lisbon, opening the sea route from Europe around the Cape of Good Hope to India." },
  "07-09": { year: 1816, zh: "阿根廷在图库曼宣布脱离西班牙独立，拉普拉塔的独立浪潮再进一步。", en: "Argentina declares independence from Spain at Tucumán, a landmark in South America's liberation." },
  "07-10": { year: 1962, zh: "第一颗通信卫星“电星 1 号”发射升空，首次把电视信号直播跨越大西洋。", en: "Telstar 1, the first communications satellite, launches and relays the first live television signals across the Atlantic." },
  "07-12": { year: 1962, zh: "滚石乐队在伦敦举行首场演出，一支定义了摇滚乐的乐队就此登台。", en: "The Rolling Stones play their first concert in London, launching a band that would define rock and roll." },
  "07-13": { year: 1985, zh: "“拯救生命”大型慈善演唱会在伦敦和费城同步举行，全球近 20 亿人收看，为非洲饥荒募款。", en: "Live Aid stages simultaneous concerts in London and Philadelphia, watched by nearly two billion people to raise funds for famine relief in Africa." },
  "07-15": { year: 1099, zh: "第一次十字军攻陷耶路撒冷，结束了这场远征最漫长的一次围城。", en: "Crusaders of the First Crusade capture Jerusalem, ending the long siege that crowned their expedition." },
  "07-17": { year: 1955, zh: "加州迪士尼乐园开园，华特·迪士尼把动画世界变成了可以走进去的主题乐园。", en: "Disneyland opens in California, as Walt Disney turns his animated world into a theme park you can walk through." },
  "07-18": { year: 1976, zh: "14 岁的科马内奇在蒙特利尔奥运会上拿到体操史上第一个 10 分满分。", en: "Fourteen-year-old Nadia Comăneci scores the first perfect 10 in Olympic gymnastics history at the Montreal Games." },
  "07-19": { year: 1903, zh: "首届环法自行车赛在巴黎收官，莫里斯·加兰赢得总冠军，这项传奇赛事就此诞生。", en: "The first Tour de France finishes in Paris, with Maurice Garin winning a race that becomes a sporting legend." },
  "07-21": { year: 1960, zh: "班达拉奈克夫人出任锡兰总理，成为现代史上第一位民选女性政府首脑。", en: "Sirimavo Bandaranaike becomes prime minister of Ceylon, the world's first elected female head of government in modern history." },
  "07-22": { year: 1933, zh: "威利·波斯特单人驾驶飞机降落纽约，完成人类首次单人环球飞行，用时不到八天。", en: "Wiley Post lands in New York to complete the first solo flight around the world, in under eight days." },
  "07-23": { year: 1921, zh: "中国共产党第一次全国代表大会在上海开幕，会议最后转移到嘉兴南湖的游船上完成。", en: "The First National Congress of the Chinese Communist Party opens in Shanghai, later finishing aboard a boat on South Lake in Jiaxing." },
  "07-24": { year: 1911, zh: "美国探险家宾厄姆抵达秘鲁的马丘比丘，这座印加古城重新为世人所知。", en: "American explorer Hiram Bingham reaches Machu Picchu in Peru, bringing the Inca citadel back to the world's attention." },
  "07-26": { year: 1956, zh: "埃及总统纳赛尔宣布将苏伊士运河收归国有，震动了全世界。", en: "Egyptian president Gamal Abdel Nasser nationalizes the Suez Canal, sending shockwaves around the world." },
  "07-27": { year: 1953, zh: "朝鲜停战协定在板门店签署，朝鲜战争的枪声就此停息。", en: "The Korean Armistice Agreement is signed at Panmunjom, silencing the guns of the Korean War." },
  "07-29": { year: 1958, zh: "美国国家航空航天局（NASA）成立，人类的太空竞赛翻开新的一页。", en: "NASA is founded in the United States, opening a new chapter in the space race." },
  "07-30": { year: 1966, zh: "英格兰队在伦敦加时击败西德，夺得世界杯冠军——至今仍是他们唯一的一座。", en: "England beats West Germany in extra time in London to win the World Cup, still their only title." },
  "07-31": { year: 1964, zh: "美国“游骑兵 7 号”在撞向月球前传回首批月球近距离照片。", en: "NASA's Ranger 7 sends back the first close-up photographs of the Moon before crashing into its surface." },
  "08-02": { year: 1990, zh: "伊拉克入侵科威特，海湾危机爆发，世界为之震动。", en: "Iraq invades Kuwait, triggering the Gulf Crisis and shocking the world." },
  "08-03": { year: 1492, zh: "哥伦布率三艘船从西班牙启航西行，寻找通往亚洲的新航路。", en: "Christopher Columbus sets sail from Spain with three ships, seeking a westward route to Asia." },
  "08-05": { year: 1963, zh: "美、英、苏在莫斯科签署《部分禁止核试验条约》，禁止在大气层、外层空间和水下核试验。", en: "The United States, Britain and the Soviet Union sign the Partial Test Ban Treaty in Moscow, banning nuclear tests in the atmosphere, space and underwater." },
  "08-07": { year: 1974, zh: "法国杂技艺人菲利普·珀蒂在纽约世贸双塔之间走钢丝，离地 400 多米。", en: "French high-wire artist Philippe Petit walks a tightrope between New York's Twin Towers, more than 400 metres above the ground." },
  "08-08": { year: 2008, zh: "北京奥运会开幕，中国第一次迎来奥林匹克盛会。", en: "The Beijing Olympic Games open, bringing the Olympics to China for the first time." },
  "08-10": { year: 1519, zh: "麦哲伦率船队从西班牙启航，开始了人类历史上首次环球航行。", en: "Ferdinand Magellan's expedition sets sail from Spain, beginning the first circumnavigation of the Earth." },
  "08-11": { year: 1999, zh: "20 世纪最后一次日全食横扫欧洲和亚洲，数千万人仰头观赏天狗食日。", en: "The last total solar eclipse of the 20th century sweeps across Europe and Asia, watched by tens of millions." },
  "08-13": { year: 1961, zh: "东德连夜开始修建柏林墙，一座城市从此被一分为二。", en: "East Germany begins building the Berlin Wall overnight, dividing a city in two." },
  "08-14": { year: 1947, zh: "巴基斯坦脱离英属印度独立，穆罕默德·阿里·真纳成为首任总督。", en: "Pakistan gains independence from British India, with Muhammad Ali Jinnah as its first governor-general." },
  "08-16": { year: 1977, zh: "“猫王”埃尔维斯·普雷斯利在孟菲斯逝世，年仅 42 岁，摇滚乐的一个时代落幕。", en: "Elvis Presley, the 'King of Rock and Roll', dies in Memphis aged 42, closing an era in popular music." },
  "08-17": { year: 1945, zh: "苏加诺和哈达在雅加达宣告印度尼西亚独立。", en: "Sukarno and Mohammad Hatta proclaim Indonesia's independence in Jakarta." },
  "08-18": { year: 1868, zh: "法国天文学家让森在日全食光谱中发现一条陌生的黄线——这就是氦，先在太阳上被发现的元素。", en: "During a total solar eclipse, French astronomer Pierre Janssen spots an unknown yellow spectral line: helium, an element found on the Sun before Earth." },
  "08-19": { year: 1960, zh: "苏联发射“卫星 5 号”，小狗贝尔卡和斯特雷尔卡成为首批平安返回地球的太空旅客。", en: "The Soviet Union launches Sputnik 5; dogs Belka and Strelka become the first living creatures to return safely from orbit." },
  "08-20": { year: 1977, zh: "“旅行者 2 号”探测器发射升空，踏上拜访四颗外行星的漫长旅程。", en: "NASA launches Voyager 2, beginning its grand tour of the outer planets." },
  "08-22": { year: 1864, zh: "12 国代表在日内瓦签署第一部《日内瓦公约》，战地救护从此有了国际规则，红十字运动随之壮大。", en: "Twelve nations sign the First Geneva Convention, giving battlefield care international rules and boosting the Red Cross movement." },
  "08-23": { year: 1939, zh: "苏德两国签署《互不侵犯条约》，欧洲在二战前夜又添变数。", en: "The Soviet Union and Nazi Germany sign a non-aggression pact, reshaping Europe on the eve of World War II." },
  "08-25": { year: 1944, zh: "巴黎解放：盟军和法国抵抗力量进入巴黎，结束了四年的德军占领。", en: "Paris is liberated, as Allied and French Resistance forces enter the city and end four years of German occupation." },
  "08-26": { year: 1920, zh: "美国宪法第十九修正案正式生效，美国女性赢得全国范围的投票权。", en: "The Nineteenth Amendment takes effect in the United States, guaranteeing women the right to vote nationwide." },
  "08-27": { year: 1883, zh: "印度尼西亚喀拉喀托火山爆发达到顶峰，巨响传遍数千公里，是人类有记录以来最剧烈的火山喷发之一。", en: "Krakatoa erupts at its peak in Indonesia, a blast heard thousands of kilometres away and among the most violent eruptions ever recorded." },
  "08-29": { year: 1966, zh: "披头士在旧金山举行最后一场售票演唱会，此后乐队退出巡演、专注于录音室。", en: "The Beatles play their last ticketed concert in San Francisco, retiring from touring to focus on the studio." },
  "08-30": { year: 1963, zh: "美苏“热线”正式开通，华盛顿与莫斯科之间有了直通电话，以防核误判。", en: "The Moscow–Washington hotline goes into service, giving the superpowers a direct link to prevent nuclear miscalculation." },
  "09-03": { year: 1783, zh: "《巴黎条约》签署，美国独立战争正式结束，英国承认美国独立。", en: "The Treaty of Paris is signed, formally ending the American Revolutionary War as Britain recognizes American independence." },
  "09-04": { year: 1998, zh: "谷歌在加利福尼亚州门洛帕克成立，日后成长为全球最大的搜索引擎公司。", en: "Google is founded in Menlo Park, California, and goes on to become the world's largest search engine company." },
  "09-05": { year: 1977, zh: "美国发射旅行者 1 号探测器，它如今是距地球最远的人造物体。", en: "NASA launches the Voyager 1 probe, now the most distant human-made object from Earth." },
  "09-06": { year: 1522, zh: "埃尔卡诺率维多利亚号回到西班牙，完成人类首次环球航行。", en: "Elcano brings the Victoria back to Spain, completing the first circumnavigation of the globe." },
  "09-07": { year: 1822, zh: "巴西宣布脱离葡萄牙独立，佩德罗一世成为巴西帝国的缔造者。", en: "Brazil declares independence from Portugal, with Pedro I becoming the founder of the Empire of Brazil." },
  "09-09": { year: 1976, zh: "毛泽东在北京逝世，结束了他对中国长达数十年的领导。", en: "Mao Zedong dies in Beijing, ending his decades-long leadership of China." },
  "09-10": { year: 2008, zh: "欧洲核子研究中心的大型强子对撞机首次实现质子束流运行。", en: "CERN's Large Hadron Collider is powered up for the first time, circulating its first proton beam." },
  "09-13": { year: 1993, zh: "以色列与巴解组织在华盛顿签署《奥斯陆协议》，拉宾与阿拉法特握手言和。", en: "Israel and the PLO sign the Oslo I Accord in Washington, sealed by a handshake between Rabin and Arafat." },
  "09-14": { year: 1814, zh: "弗朗西斯·斯科特·基目睹麦克亨利堡之战后，写下后来成为美国国歌的诗篇。", en: "Francis Scott Key writes the poem that becomes the US national anthem after witnessing the Battle of Fort McHenry." },
  "09-16": { year: 1810, zh: "伊达尔戈神父发出多洛雷斯呼声，墨西哥独立战争就此拉开序幕。", en: "Father Hidalgo issues the Cry of Dolores, launching Mexico's war of independence from Spain." },
  "09-18": { year: 1851, zh: "《纽约时报》创刊，日后成为美国最具影响力的报纸之一。", en: "The New York Times is founded, later becoming one of America's most influential newspapers." },
  "09-19": { year: 1893, zh: "新西兰成为世界上第一个赋予妇女选举权的国家。", en: "New Zealand becomes the first country in the world to grant women the right to vote." },
  "09-20": { year: 1519, zh: "麦哲伦率五艘船从西班牙启航，开启人类首次环球航行的尝试。", en: "Magellan sets sail from Spain with five ships, beginning the first attempt to circumnavigate the globe." },
  "09-22": { year: 1862, zh: "林肯发表《预备解放宣言》，宣布将解放南方叛乱州的奴隶。", en: "Lincoln issues the preliminary Emancipation Proclamation, declaring freedom for enslaved people in the rebelling states." },
  "09-23": { year: 1846, zh: "天文学家伽勒在柏林首次观测到海王星，证实了勒维耶的计算预言。", en: "Astronomer Galle first observes Neptune in Berlin, confirming Le Verrier's mathematical prediction." },
  "09-24": { year: 1948, zh: "本田技研工业在日本成立，日后发展为全球知名的汽车与摩托车制造商。", en: "Honda Motor Company is founded in Japan, later growing into a world-renowned car and motorcycle maker." },
  "09-25": { year: 1513, zh: "巴尔沃亚成为首位望见太平洋东岸的欧洲人。", en: "Balboa becomes the first European to sight the eastern shore of the Pacific Ocean." },
  "09-28": { year: 1066, zh: "征服者威廉率诺曼军队在英格兰佩文西登陆，开启诺曼征服。", en: "William the Conqueror lands at Pevensey in England with his Norman army, beginning the Norman Conquest." },
  "09-29": { year: 1954, zh: "欧洲核子研究中心 CERN 正式成立，成为世界最大的粒子物理实验室。", en: "CERN is formally founded, becoming the world's largest particle physics laboratory." },
  "09-30": { year: 1791, zh: "莫扎特的歌剧《魔笛》在维也纳首演，仅两个多月后他便与世长辞。", en: "Mozart's opera The Magic Flute premieres in Vienna, just over two months before his death." },
  "10-03": { year: 1990, zh: "东德正式并入西德，分裂四十余年的德国实现统一。", en: "East Germany formally joins West Germany, reunifying the country after more than forty years of division." },
  "10-05": { year: 1962, zh: "披头士发行首支单曲《Love Me Do》，开启了他们的传奇之路。", en: "The Beatles release their first single, Love Me Do, beginning their legendary career." },
  "10-06": { year: 1927, zh: "首部有声电影《爵士歌王》在纽约首映，电影就此进入有声时代。", en: "The Jazz Singer, the first feature-length talkie, premieres in New York, ushering cinema into the sound era." },
  "10-07": { year: 1959, zh: "苏联月球 3 号拍下人类历史上首批月球背面照片。", en: "The Soviet Luna 3 probe takes the first photographs in history of the far side of the Moon." },
  "10-09": { year: 1940, zh: "约翰·列侬出生于利物浦，日后与保罗·麦卡特尼共同组建披头士乐队。", en: "John Lennon is born in Liverpool; he later co-founds the Beatles with Paul McCartney." },
  "10-10": { year: 1911, zh: "武昌起义爆发，辛亥革命拉开序幕，清朝统治自此走向终结。", en: "The Wuchang Uprising erupts, sparking the Xinhai Revolution that brings Qing rule to an end." },
  "10-11": { year: 1968, zh: "阿波罗 7 号发射升空，成为阿波罗计划首次载人飞行任务。", en: "Apollo 7 lifts off, becoming the first crewed mission of NASA's Apollo program." },
  "10-12": { year: 1492, zh: "哥伦布抵达美洲，在巴哈马群岛登陆，开启欧洲与美洲持续往来的时代。", en: "Columbus reaches the Americas, landing in the Bahamas and opening an era of sustained contact between Europe and the New World." },
  "10-13": { year: 1884, zh: "国际子午线会议投票选定格林尼治子午线为全球本初子午线。", en: "The International Meridian Conference votes to adopt the Greenwich meridian as the world's prime meridian." },
  "10-15": { year: 1582, zh: "格里高利历在意大利、西班牙等地正式启用，这一天成为新历的第一天。", en: "The Gregorian calendar comes into force in Italy, Spain and elsewhere, with this day as its first date." },
  "10-17": { year: 1777, zh: "英军在萨拉托加向美军投降，成为美国独立战争的重要转折点。", en: "British forces surrender at Saratoga, a major turning point in the American Revolutionary War." },
  "10-18": { year: 1867, zh: "美国正式从俄国手中接管阿拉斯加，这片土地以约 720 万美元售出。", en: "The United States formally takes possession of Alaska from Russia, purchased for about 7.2 million dollars." },
  "10-20": { year: 1973, zh: "悉尼歌剧院正式揭幕，其独特的帆形屋顶成为澳大利亚的象征。", en: "The Sydney Opera House officially opens, its distinctive sail-like roof becoming a symbol of Australia." },
  "10-22": { year: 1962, zh: "肯尼迪总统向全国发表电视讲话，公开古巴导弹危机并宣布海上隔离。", en: "President Kennedy addresses the nation on television, revealing the Cuban Missile Crisis and announcing a naval quarantine." },
  "10-23": { year: 1956, zh: "匈牙利十月事件爆发，布达佩斯民众走上街头抗议苏联控制。", en: "The Hungarian Revolution begins as crowds in Budapest take to the streets against Soviet control." },
  "10-25": { year: 1881, zh: "巴勃罗·毕加索出生于西班牙马拉加，日后成为 20 世纪最具影响力的画家之一。", en: "Pablo Picasso is born in Málaga, Spain, later becoming one of the most influential artists of the 20th century." },
  "10-26": { year: 1965, zh: "披头士四名成员在白金汉宫接受女王授予的大英帝国员佐勋章。", en: "The four Beatles receive their MBE medals from the Queen at Buckingham Palace." },
  "10-27": { year: 1904, zh: "纽约地铁正式开通，第一条线路从市政厅站通往哈莱姆。", en: "The New York City Subway officially opens, its first line running from City Hall to Harlem." },
  "10-28": { year: 1886, zh: "自由女神像在纽约港正式揭幕，成为美国自由与民主的象征。", en: "The Statue of Liberty is dedicated in New York Harbor, becoming a symbol of American freedom and democracy." },
  "10-30": { year: 1974, zh: "阿里在金沙萨的丛林之战中击倒福尔曼，夺回世界重量级拳王头衔。", en: "Muhammad Ali knocks out George Foreman in Kinshasa's Rumble in the Jungle to regain the world heavyweight title." },
  "11-01": { year: 1512, zh: "米开朗基罗的西斯廷教堂天顶画首次向公众展出，文艺复兴的巅峰之作就此亮相。", en: "Michelangelo's Sistine Chapel ceiling is exhibited to the public for the first time, unveiling a masterpiece of the Renaissance." },
  "11-02": { year: 1936, zh: "英国广播公司开通世界上第一个定期的电视广播服务，电视时代正式开启。", en: "The BBC launches the world's first regular television broadcast service, opening the television age." },
  "11-03": { year: 1957, zh: "苏联将小狗莱卡送入太空，它成为第一个进入地球轨道的动物。", en: "The Soviet Union sends the dog Laika into space; she becomes the first animal to orbit the Earth." },
  "11-06": { year: 1860, zh: "亚伯拉罕·林肯当选美国总统，美国随即滑向内战的边缘。", en: "Abraham Lincoln is elected President of the United States, as the country slides toward civil war." },
  "11-07": { year: 1917, zh: "布尔什维克在彼得格勒发动十月革命，夺取政权，世界格局为之改变。", en: "The Bolsheviks seize power in Petrograd in the October Revolution, reshaping the world order." },
  "11-08": { year: 1895, zh: "伦琴在实验中发现 X 射线，医学从此多了一双透视的眼睛。", en: "Wilhelm Röntgen discovers X-rays, giving medicine a way to see inside the human body." },
  "11-10": { year: 1969, zh: "儿童节目《芝麻街》在美国首播，此后陪伴了全世界几代孩子的成长。", en: "The children's programme Sesame Street premieres in the United States, going on to teach generations of children worldwide." },
  "11-12": { year: 1990, zh: "伯纳斯-李与卡约发表万维网的正式提案，网页互联的世界有了蓝图。", en: "Tim Berners-Lee and Robert Cailliau publish their formal proposal for the World Wide Web, a blueprint for a world of linked pages." },
  "11-13": { year: 1907, zh: "法国人保罗·科尔尼驾驶自制的双旋翼直升机完成首次自由飞行，离地虽低，却是直升机史上的第一步。", en: "Paul Cornu makes the first free flight of a helicopter in France; it barely leaves the ground, but it is a first step in rotary-wing aviation." },
  "11-15": { year: 1920, zh: "国际联盟在日内瓦召开第一次大会，这个维护世界和平的新机构开始运转。", en: "The League of Nations holds its first assembly in Geneva, as the new body meant to keep world peace begins its work." },
  "11-16": { year: 1945, zh: "联合国教科文组织在伦敦成立，以教育、科学和文化促进和平。", en: "UNESCO is founded in London, charged with building peace through education, science and culture." },
  "11-18": { year: 1928, zh: "动画短片《汽船威利号》上映，米老鼠第一次与观众见面。", en: "The cartoon Steamboat Willie is released, marking Mickey Mouse's first appearance before the public." },
  "11-20": { year: 1947, zh: "英国伊丽莎白公主与菲利普亲王在伦敦威斯敏斯特教堂举行婚礼。", en: "Princess Elizabeth marries Philip Mountbatten at Westminster Abbey in London." },
  "11-21": { year: 1969, zh: "阿帕网在加州大学洛杉矶分校与斯坦福研究院之间建立第一条永久连接，互联网的雏形初现。", en: "The first permanent ARPANET link is established between UCLA and the Stanford Research Institute, an early ancestor of the Internet." },
  "11-25": { year: 1915, zh: "爱因斯坦向普鲁士科学院提交广义相对论的场方程，引力被重新理解为时空的弯曲。", en: "Einstein presents the field equations of general relativity to the Prussian Academy, recasting gravity as the curvature of spacetime." },
  "11-27": { year: 1895, zh: "诺贝尔签署遗嘱，将大部分遗产用于设立诺贝尔奖。", en: "Alfred Nobel signs his will, leaving most of his fortune to establish the Nobel Prizes." },
  "11-28": { year: 1520, zh: "麦哲伦船队穿过后来以他命名的海峡，首次驶入太平洋。", en: "Magellan's expedition sails through the strait that now bears his name and enters the Pacific Ocean for the first time." },
  "11-29": { year: 1947, zh: "联合国大会通过巴勒斯坦分治决议，计划在当地建立犹太国与阿拉伯国。", en: "The UN General Assembly adopts the partition plan for Palestine, proposing separate Jewish and Arab states." },
  "11-30": { year: 1872, zh: "苏格兰与英格兰进行历史上第一场国际足球比赛，双方以 0 比 0 握手言和。", en: "Scotland and England play the first-ever international football match; it ends in a goalless draw." },
  "12-02": { year: 1942, zh: "费米领导的团队在芝加哥实现人类首次自持核链式反应，原子时代的大门被推开。", en: "Enrico Fermi's team achieves the first self-sustaining nuclear chain reaction in Chicago, opening the atomic age." },
  "12-04": { year: 1829, zh: "英属印度颁布条例，宣布寡妇殉葬的「萨蒂」习俗为非法，印度社会改革迈出重要一步。", en: "British India outlaws sati, the practice of widow immolation, in a landmark moment for social reform in India." },
  "12-05": { year: 1933, zh: "美国第二十一修正案获得批准，长达十三年的禁酒令正式结束。", en: "The Twenty-first Amendment is ratified in the United States, ending thirteen years of Prohibition." },
  "12-06": { year: 1917, zh: "芬兰宣布脱离俄国独立，这一天后来成为芬兰的独立日。", en: "Finland declares its independence from Russia; the date is now celebrated as Finland's Independence Day." },
  "12-08": { year: 1991, zh: "俄罗斯、白俄罗斯与乌克兰领导人签署《别洛韦日协定》，宣布苏联不复存在。", en: "The leaders of Russia, Belarus and Ukraine sign the Belovezha Accords, declaring that the Soviet Union has ceased to exist." },
  "12-11": { year: 1946, zh: "联合国儿童基金会成立，为战后各国的儿童提供紧急援助。", en: "UNICEF is founded to provide emergency aid to children in countries devastated by the Second World War." },
  "12-12": { year: 1901, zh: "马可尼接收到从英国跨越大西洋传来的无线电信号，无线通信进入新纪元。", en: "Guglielmo Marconi receives the first transatlantic radio signal, sent from England, ushering in a new era of wireless communication." },
  "12-13": { year: 1577, zh: "弗朗西斯·德雷克从英格兰启航，开始了英国人的第一次环球航行。", en: "Francis Drake sets sail from England on the voyage that will become the first English circumnavigation of the globe." },
  "12-16": { year: 1773, zh: "波士顿倾茶事件爆发，殖民地居民将英国茶叶倒入海中，美国独立的导火索被点燃。", en: "In the Boston Tea Party, American colonists dump British tea into the harbour, lighting a fuse of the American Revolution." },
  "12-18": { year: 1865, zh: "美国宪法第十三修正案正式生效，奴隶制在全美被废除。", en: "The Thirteenth Amendment takes effect in the United States, abolishing slavery throughout the country." },
  "12-19": { year: 1843, zh: "狄更斯的中篇小说《圣诞颂歌》出版，小气鬼斯克鲁奇的故事从此成为圣诞经典。", en: "Charles Dickens's A Christmas Carol is published; the tale of Ebenezer Scrooge becomes a Christmas classic." },
  "12-20": { year: 1999, zh: "中国政府恢复对澳门行使主权，澳门回归祖国。", en: "China resumes sovereignty over Macao, as the Portuguese-administered territory is handed back." },
  "12-21": { year: 1913, zh: "《纽约世界报》刊登历史上第一个纵横填字游戏，这种文字游戏很快风靡全球。", en: "The New York World publishes the first crossword puzzle; the word game soon becomes a worldwide craze." },
  "12-22": { year: 1989, zh: "被柏林墙封隔二十八年的勃兰登堡门重新开放，科尔走过大门与莫德罗会面。", en: "The Brandenburg Gate, sealed off by the Berlin Wall for 28 years, is reopened, as Chancellor Kohl walks through to meet Hans Modrow." },
  "12-23": { year: 1947, zh: "巴丁与布拉顿在贝尔实验室首次演示晶体管，现代电子学的基石就此诞生。", en: "Bardeen and Brattain demonstrate the first transistor at Bell Laboratories, laying a cornerstone of modern electronics." },
  "12-24": { year: 1914, zh: "第一次世界大战前线出现「圣诞休战」，交战双方士兵走出战壕，互赠礼物、一起踢球。", en: "The Christmas Truce begins on the Western Front, as opposing soldiers leave their trenches to exchange gifts and play football." },
  "12-26": { year: 1898, zh: "居里夫妇向法国科学院宣布发现新元素镭，「放射性」研究翻开新页。", en: "Marie and Pierre Curie announce their discovery of the new element radium to the French Academy of Sciences." },
  "12-28": { year: 1895, zh: "卢米埃尔兄弟在巴黎举行第一次公开电影放映，电影正式登上历史舞台。", en: "The Lumière brothers hold the first public film screening in Paris, and cinema takes the stage of history." },
  "12-29": { year: 1845, zh: "得克萨斯正式加入美国，成为美国的第二十八个州。", en: "Texas is admitted to the United States, becoming its 28th state." },
  "12-31": { year: 1879, zh: "爱迪生在门洛帕克首次公开演示白炽灯，实验室与街道被电灯照亮，迎接新年。", en: "Edison gives the first public demonstration of his incandescent light at Menlo Park, lighting up the laboratory to greet the new year." },
};

/* ---------- Thoughts (bilingual pairs) ---------- */
const THOUGHTS = [
  { id: "thought:001", zh: "你以为你在回忆，其实你每回忆一次，就重写了一次记忆。", en: "You think you are remembering. Each time you recall something, you rewrite the memory a little." },
  { id: "thought:002", zh: "注意力是你唯一真正拥有的货币，花在哪里，你的人生就在哪里。", en: "Attention is the only currency you truly own. Where you spend it is where your life happens." },
  { id: "thought:003", zh: "大脑不是用来存真相的，它是用来预测下一秒的。预测错了，才轮到学习。", en: "The brain is not built to store truth. It is built to predict the next second, and it learns only when the prediction fails." },
  { id: "thought:004", zh: "你确信的事里，有相当一部分只是你重复听说过很多次。", en: "A fair share of what you are certain of is simply what you have heard repeated many times." },
  { id: "thought:005", zh: "无聊不是没有事情做，是所有事情都没有先抓住你的注意力。", en: "Boredom is not having nothing to do. It is nothing having caught your attention first." },
  { id: "thought:006", zh: "选择困难往往不是选项太多，而是你还没决定用什么标准选。", en: "Hard choices are rarely about too many options. They are about not yet having decided what counts as a reason." },
  { id: "thought:007", zh: "你读过的书大多会忘掉，但忘掉之后剩下的形状，就是你的判断力。", en: "You will forget most of what you read. What remains after forgetting is the shape of your judgement." },
  { id: "thought:008", zh: "地图不是领土，模型不是现实，时钟也不是时间本身，它只是我们约定好的一种看法。", en: "The map is not the territory, the model is not reality, and the clock is not time itself. It is only an agreed way of looking." },
  { id: "thought:009", zh: "人会高估一天能做的事，低估一年能做的事。时钟只管走，不负责纠正这个错觉。", en: "We overestimate what a day can hold and underestimate what a year can. The clock just keeps walking; correcting the illusion is on us." },
  { id: "thought:010", zh: "确定性让人安心，偶然性让人活着。两者缺一个，日子都不完整。", en: "Certainty comforts us; chance keeps us alive to possibility. A day missing either one is incomplete." },
  { id: "thought:011", zh: "你此刻觉得漫长的一分钟，回忆起来往往只剩一个模糊的影子。时间在感受里从来不是匀速的。", en: "A minute that feels endless now will shrink to a blur in memory. In felt experience, time never runs at a constant speed." },
  { id: "thought:012", zh: "问题比答案活得久。一个好问题，可以陪你走很多年。", en: "Questions outlive answers. A good question can keep you company for years." },
  { id: "thought:013", zh: "所谓灵感，常常是注意力在别处闲逛时，替你带回来的东西。", en: "What we call inspiration is often just attention, wandering elsewhere, bringing something back for you." },
  { id: "thought:014", zh: "你无法同时抓住这一秒和回味上一秒。意识的带宽，只够选一个。", en: "You cannot hold this second and savour the last one at the same time. Consciousness has bandwidth for one." },
  { id: "thought:015", zh: "时间不会治愈什么，是你在时间里做的事治愈了你。时钟只是个见证者。", en: "Time itself heals nothing. What you do inside the time does the healing. The clock is only a witness." },
  { id: "thought:016", zh: "等红灯时觉得漫长，是因为你的注意力全压在等待本身上。时间感，是注意力的副产品。", en: "A red light feels long because all your attention is pressed onto the waiting itself. Felt time is a by-product of attention." },
  { id: "thought:017", zh: "机会常常伪装成偶然，敲门时声音很小。听不见的人，会说自己运气不好。", en: "Opportunity often arrives disguised as chance, and knocks quietly. Those who miss it call themselves unlucky." },
  { id: "thought:018", zh: "骰子没有记忆。你连输十把，第十一把的概率，和第一把一模一样。", en: "Dice have no memory. Lose ten throws in a row, and the eleventh is exactly as likely as the first." },
  { id: "thought:019", zh: "人最容易犯的错，是拿最坏的一天，去估计整个人生。", en: "The easiest mistake is to judge a whole life by its worst day." },
  { id: "thought:020", zh: "你刷到的信息流不是世界，是为你停留时长优化过的世界切片。", en: "Your feed is not the world. It is a slice of the world optimised for how long you will stay." },
  { id: "thought:021", zh: "专注不是把注意力锁住，是走神之后，一次次把它领回来。", en: "Focus is not locking attention in place. It is bringing it back, again and again, after it wanders." },
  { id: "thought:022", zh: "很多焦虑来自一个错觉：以为别人都在看着你。其实每个人都忙着担心自己被看。", en: "Much anxiety rests on an illusion: that everyone is watching you. In truth, everyone is busy worrying about being watched." },
  { id: "thought:023", zh: "计划赶不上变化，不是因为计划没用，是因为变化从不按计划的粒度来。", en: "Plans fail to keep up with change not because planning is useless, but because change never arrives at the granularity of the plan." },
  { id: "thought:024", zh: "你做的每一个决定，都在悄悄替未来的你投票。票数攒够了，就成了习惯。", en: "Every decision is a quiet vote cast for your future self. Enough votes, and it becomes a habit." },
  { id: "thought:025", zh: "所谓自律，很多时候只是把诱惑放得远一点，把好事放得近一点。意志力的事，多半是距离的事。", en: "Much of self-discipline is just distance: temptations placed farther away, good things placed closer. Willpower is often geometry." },
  { id: "thought:026", zh: "大脑喜欢故事胜过喜欢数据。一个生动的个例，常常打败一万个统计数字。", en: "The brain prefers stories to data. One vivid anecdote routinely defeats ten thousand statistics." },
  { id: "thought:027", zh: "你对概率的直觉，在小事上够用，在大事上常常系统地出错。彩票和保险，都是卖给这个直觉的。", en: "Your intuition for probability works for small things and fails systematically for big ones. Lotteries and insurance are both sold to that intuition." },
  { id: "thought:028", zh: "把一天过很多次，不等于活了很多天。新鲜感退潮的地方，时间也跟着变薄。", en: "Living the same day many times over is not the same as living many days. Where novelty ebbs, time thins out too." },
  { id: "thought:029", zh: "记忆偏爱开头和结尾，中间的大段会被悄悄压缩。所以旅行的第一天和最后一天，总是显得最长。", en: "Memory favours beginnings and endings and quietly compresses the middle. That is why the first and last days of a trip feel the longest." },
  { id: "thought:030", zh: "等待的时候，时间是黏的；忙起来的时候，时间是滑的。同一个小时，两种质地。", en: "Time is sticky when you wait and slippery when you are busy. The same hour, two different textures." },
  { id: "thought:031", zh: "你此刻的烦恼，五年后大概率只剩一个模糊的轮廓。但此刻的欢喜，也一样。珍惜要趁现在。", en: "Today's worry will most likely be a faint outline in five years. So will today's joy. Cherishing has to happen now." },
  { id: "thought:032", zh: "认知最难的一步，不是接受新想法，是发现旧想法错了还舍不得放手。", en: "The hardest step in thinking is not accepting a new idea. It is letting go of an old one you have grown fond of." },
  { id: "thought:033", zh: "你以为选择在消耗你，其实是没有标准在消耗你。标准一旦立住，选择就变快了。", en: "It is rarely the choosing that exhausts you. It is the absence of a criterion. Once the standard stands, choosing speeds up." },
  { id: "thought:034", zh: "所谓成长，常常是同一件事，隔了几年再看，完全看出另一层意思。", en: "Growth is often this: the same event, seen years later, reveals a completely different layer of meaning." },
  { id: "thought:035", zh: "运气是概率穿上个人叙事的外衣。同一场雨，落在赶路人头上叫倒霉，落在久旱的田里叫及时。", en: "Luck is probability wearing the clothes of a personal story. The same rain is misfortune on a traveller and timely on a dry field." },
  { id: "thought:036", zh: "你永远不知道哪一次是最后一次。所以有些事，值得当作最后一次来做。", en: "You never know which time is the last time. Some things are worth doing as if they were." },
  { id: "thought:037", zh: "大脑会把重复的东西自动略过。日子显得越来越快，不是因为时间变了，是因为你跳过了太多页。", en: "The brain automatically skims what repeats. Days feel faster not because time changed, but because you skipped so many pages." },
  { id: "thought:038", zh: "一个想法在脑子里转一百遍，不如写下来看一遍。写下来的念头，才开始接受检验。", en: "An idea circling in your head a hundred times is worth less than writing it down once. Only on paper does a thought start facing tests." },
  { id: "thought:039", zh: "你羡慕别人的生活，多半是拿自己的幕后花絮，去比人家的正片。", en: "Envy usually compares your behind-the-scenes footage with someone else's finished film." },
  { id: "thought:040", zh: "注意力放在哪里，时间就流向哪里。回头看，一生就是注意力流过的河道。", en: "Time flows where attention goes. Looking back, a life is the riverbed carved by attention." },
  { id: "thought:041", zh: "偶然不是没有原因，是原因多到你数不过来，于是你给它起了个名字叫命运。", en: "Chance is not causeless. It is causes too many to count, and so we give the sum a name: fate." },
  { id: "thought:042", zh: "对未来的预测，最准的往往不是最聪明的那个，而是最愿意改口的那个。", en: "The best forecasters are rarely the cleverest. They are the ones most willing to change their minds." },
  { id: "thought:043", zh: "你读一本书，书也在读你：它标出了你此刻在意什么。隔几年重读，标出的地方全变了。", en: "When you read a book, the book reads you back: your highlights mark what you care about now. Reread it years later and the marks have all moved." },
  { id: "thought:044", zh: "遗忘不是记忆的故障，是它的功能。大脑要是全记住，你就没法思考了。", en: "Forgetting is not a bug in memory. It is one of its features. A brain that kept everything could not think." },
  { id: "thought:045", zh: "此刻这一秒，全球有几十亿人正和你一起经历它，每个人分到的内容完全不同。这就是同时性最奇妙的地方。", en: "This very second is being lived by billions of people at once, each receiving completely different contents. That is the strangest part of simultaneity." },
  { id: "thought:046", zh: "把目标说给太多人听，大脑会误以为已经完成了一部分。沉默地做事，有时跑得更快。", en: "Announce a goal too widely and the brain mistakes the applause for partial completion. Working in silence sometimes moves faster." },
  { id: "thought:047", zh: "情绪是天气，性格是气候。不要拿一天的天气，去定义一地的气候。", en: "Emotions are weather; character is climate. Do not define a place's climate by one day's weather." },
  { id: "thought:048", zh: "你总说等有时间再做。其实时间从来不是等来的，是从别的事情里让出来的。", en: "You keep saying you will do it when you have time. Time is never found waiting. It is yielded by other things." },
  { id: "thought:049", zh: "小概率事件乘以足够多的次数，就会变成必然。活得久了，谁都会遇上几次奇迹和几次意外。", en: "A small probability, multiplied by enough trials, becomes a certainty. Live long enough and everyone meets a few miracles and a few accidents." },
  { id: "thought:050", zh: "判断一个人，不是看他顺境里说什么，是看他无聊的时候做什么。无聊时段，最暴露一个人。", en: "Do not judge a person by what they say in good times. Watch what they do when bored. Boredom is the most revealing hour." },
];

/* ---------- Memory prompts (bilingual, reflection only) ---------- */
const MEMORY_PROMPTS = [
  { id: "memory:001", zh: "去年的今天，你在做什么？先别查手机，试着只凭记忆想一想。", en: "What were you doing a year ago today? Try to answer from memory alone before checking your phone." },
  { id: "memory:002", zh: "想一个你很久没有联系的人。此刻，他或她大概在哪里，过着怎样的一天？", en: "Think of someone you have not contacted in a long time. Where might they be right now, living what kind of day?" },
  { id: "memory:003", zh: "你手机相册里最早的那张照片是什么？你还记得按下快门时在想什么吗？", en: "What is the oldest photo on your phone? Do you remember what you were thinking when you took it?" },
  { id: "memory:004", zh: "十年前，你以为自己现在会过怎样的生活？和此刻比，差在哪里，对在哪里？", en: "Ten years ago, what did you imagine your life would look like now? Where were you wrong, and where were you right?" },
  { id: "memory:005", zh: "有没有一句话，你听过一次就再也没忘掉？它是谁说的，在什么场合？", en: "Is there a sentence you heard once and never forgot? Who said it, and on what occasion?" },
  { id: "memory:006", zh: "想一个你曾经每天都去、现在再也不会去的地方。它还在吗？", en: "Think of a place you used to visit every day and will probably never visit again. Is it still there?" },
  { id: "memory:007", zh: "你小时候最喜欢的一首歌或一本书，现在再听、再看，会是什么感觉？", en: "A song or book you loved as a child: what would it feel like to hear or read it again now?" },
  { id: "memory:008", zh: "上一次你完全没有看时间、忘记了时间，是在做什么的时候？", en: "When did you last lose track of time completely, and what were you doing?" },
  { id: "memory:009", zh: "如果此刻能给三年前的自己留一句话，你会留什么？只许一句。", en: "If you could leave one sentence for yourself three years ago, what would it be? Only one." },
  { id: "memory:010", zh: "今天这一天里，有没有一个瞬间值得被记住？哪怕它非常小。", en: "Was there a moment today worth remembering, however small?" },
  { id: "memory:011", zh: "你记得的第一个清晨是什么样的？光线、声音、气味，随便哪一个都行。", en: "What is the earliest morning you can remember? The light, a sound, a smell, any one of them." },
  { id: "memory:012", zh: "有没有一件你学会之后就再也没忘过的技能？是谁教你的？", en: "Is there a skill you learned once and never lost? Who taught you?" },
  { id: "memory:013", zh: "想一想你人生中第一位老师的样子。你还记得他或她说过的一句话吗？", en: "Picture your very first teacher. Do you still remember a single sentence they said?" },
  { id: "memory:014", zh: "你小时候住过的房子，窗外能看到什么？闭上眼，那个画面还在吗？", en: "From the window of the home you grew up in, what could you see? Close your eyes. Is the picture still there?" },
  { id: "memory:015", zh: "有没有一顿饭，你吃过很多年了还记得味道？是在哪里、和谁一起吃的？", en: "Is there a meal whose taste you still remember after many years? Where was it, and who was with you?" },
  { id: "memory:016", zh: "想一位你曾经很佩服、后来慢慢看懂了的人。你的看法是从什么时候开始变的？", en: "Think of someone you once admired and later came to see differently. When did your view begin to change?" },
  { id: "memory:017", zh: "你第一次独自出远门是去哪里？那时的心情，现在还能找回来吗？", en: "Where did you go on your first trip away from home alone? Can you still find that feeling now?" },
  { id: "memory:018", zh: "有没有一个物件跟了你很多年，搬家都舍不得扔？它身上存着哪段日子？", en: "Is there an object that has followed you for years, surviving every move? Which chapter of your life does it hold?" },
  { id: "memory:019", zh: "回忆一下你上一次开怀大笑是因为什么。笑点本身可能已经不好笑了，但那一刻值得存档。", en: "When did you last laugh out loud, and at what? The joke may no longer be funny, but the moment is worth keeping." },
  { id: "memory:020", zh: "你曾经有一个差一点就实现的计划。它如果实现了，你现在会在哪里？", en: "You once had a plan that very nearly happened. If it had, where would you be now?" },
  { id: "memory:021", zh: "想一个已经不在的人。如果此刻能通一次一分钟的电话，你最想说什么？", en: "Think of someone who is gone. If you had a one-minute phone call with them now, what would you most want to say?" },
  { id: "memory:022", zh: "你青春里最常走的那条路，现在还在吗？路边的店换了几轮了？", en: "The road you walked most often in your youth: is it still there? How many times have its shops changed hands?" },
  { id: "memory:023", zh: "有没有一首歌，一响起前奏就能把你带回某个具体的年份？那一年发生了什么？", en: "Is there a song whose first bars take you straight back to a specific year? What happened that year?" },
  { id: "memory:024", zh: "你做过的最勇敢的一件事是什么？当时不觉得，现在回头看才发现。", en: "What is the bravest thing you have ever done? You may not have thought so at the time." },
  { id: "memory:025", zh: "想一想五年前你每天都在用、现在已经完全不用的东西。它是怎么退出你的生活的？", en: "Think of something you used every day five years ago and never touch now. How did it leave your life?" },
  { id: "memory:026", zh: "你收到过的最好的一封信或一条消息，还留着吗？写信的人现在怎么样了？", en: "Do you still have the best letter or message you ever received? How is the person who wrote it doing now?" },
  { id: "memory:027", zh: "小时候过年或过节，你家有什么雷打不动的仪式？现在还保留着吗？", en: "What ritual did your family never skip on holidays when you were a child? Does it survive today?" },
  { id: "memory:028", zh: "你第一次挣到的钱花在了什么上面？那个决定，现在看是明智还是可爱？", en: "What did you spend your first earnings on? Looking back, was it wise, or just endearing?" },
  { id: "memory:029", zh: "有没有一个地方，你只去过一次，却总觉得还会再去？它为什么留在了你心里？", en: "Is there a place you have visited only once but always felt you would return to? Why did it stay with you?" },
  { id: "memory:030", zh: "回忆一位只在你生命里出现过很短时间的人，比如旅途中的陌生人。你还记得他或她的脸吗？", en: "Recall someone who appeared in your life only briefly, a stranger on a journey perhaps. Can you still see their face?" },
  { id: "memory:031", zh: "你曾经特别想要、后来得到了却发现没那么想要的东西是什么？这个发现教会了你什么？", en: "What is something you wanted badly, got, and then found you did not want that much? What did that teach you?" },
  { id: "memory:032", zh: "如果把你的人生拍成电影，片头第一个画面会是什么？不许想太久，第一个冒出来的就是它。", en: "If your life were a film, what would its opening shot be? Do not overthink it. The first image that comes is the one." },
  { id: "memory:033", zh: "想一想你上一次感到彻底放松是什么时候、在哪里。那个场景里，时间是什么速度？", en: "When and where did you last feel completely at ease? In that scene, how fast was time moving?" },
  { id: "memory:034", zh: "你小时候最好的朋友，你们最后一次见面是什么时候？如果现在在街上遇见，第一句话会说什么？", en: "When did you last see your closest childhood friend? If you met on the street today, what would the first sentence be?" },
  { id: "memory:035", zh: "有没有一个决定，你当时觉得无关紧要，后来却改变了很多事？它是什么？", en: "Is there a decision that felt trivial at the time but changed a great deal later? What was it?" },
  { id: "memory:036", zh: "回忆一下你住过最短时间的一个地方。为什么只住了那么短？那段时间里你是什么状态？", en: "Recall the place you lived in for the shortest time. Why so brief, and what state were you in then?" },
  { id: "memory:037", zh: "你手机通讯录里，有没有一个号码，你再也不会打，但也舍不得删？", en: "Is there a number in your contacts you will never call again, yet cannot bring yourself to delete?" },
  { id: "memory:038", zh: "十年前的今天，你大概在为什么事情发愁？那件事后来怎么样了？", en: "Ten years ago today, what were you probably worrying about? How did that turn out in the end?" },
  { id: "memory:039", zh: "想一种你小时候常闻到、现在很少闻到的气味。它出现在哪里，又是怎么消失的？", en: "Think of a smell you often encountered as a child and rarely do now. Where did it live, and how did it vanish?" },
  { id: "memory:040", zh: "你有没有一句口头禅，是从某个人那里学来的？每次说出口，那个人就短暂地回来了一下。", en: "Do you have a catchphrase you picked up from someone? Every time you say it, that person briefly returns." },
  { id: "memory:041", zh: "今天的日落你看到了吗？如果没看到，上一次认真看日落是什么时候，和谁一起？", en: "Did you see today's sunset? If not, when did you last watch one properly, and who was with you?" },
];


