const CLASSICS = [
  { id: "classics:001", text: "学而时习之，不亦说乎？有朋自远方来，不亦乐乎？", source: "《论语·学而》" },
  { id: "classics:002", text: "己所不欲，勿施于人。", source: "《论语·颜渊》" },
  { id: "classics:003", text: "三人行，必有我师焉。择其善者而从之，其不善者而改之。", source: "《论语·述而》" },
  { id: "classics:004", text: "学而不思则罔，思而不学则殆。", source: "《论语·为政》" },
  { id: "classics:005", text: "知之者不如好之者，好之者不如乐之者。", source: "《论语·雍也》" },
  { id: "classics:006", text: "君子坦荡荡，小人长戚戚。", source: "《论语·述而》" },
  { id: "classics:007", text: "敏而好学，不耻下问。", source: "《论语·公冶长》" },
  { id: "classics:008", text: "温故而知新，可以为师矣。", source: "《论语·为政》" },
  { id: "classics:009", text: "逝者如斯夫，不舍昼夜。", source: "《论语·子罕》" },
  { id: "classics:010", text: "三军可夺帅也，匹夫不可夺志也。", source: "《论语·子罕》" },
  { id: "classics:011", text: "吾日三省吾身。", source: "《论语·学而》" },
  { id: "classics:012", text: "君子和而不同，小人同而不和。", source: "《论语·子路》" },
  { id: "classics:013", text: "见贤思齐焉，见不贤而内自省也。", source: "《论语·里仁》" },
  { id: "classics:014", text: "欲速则不达，见小利则大事不成。", source: "《论语·子路》" },
  { id: "classics:015", text: "工欲善其事，必先利其器。", source: "《论语·卫灵公》" },
  { id: "classics:016", text: "道可道，非常道；名可名，非常名。", source: "《道德经》" },
  { id: "classics:017", text: "上善若水。水善利万物而不争。", source: "《道德经》" },
  { id: "classics:018", text: "千里之行，始于足下。", source: "《道德经》" },
  { id: "classics:019", text: "知人者智，自知者明。", source: "《道德经》" },
  { id: "classics:020", text: "祸兮福之所倚，福兮祸之所伏。", source: "《道德经》" },
  { id: "classics:021", text: "天地不仁，以万物为刍狗。", source: "《道德经》" },
  { id: "classics:022", text: "信言不美，美言不信。", source: "《道德经》" },
  { id: "classics:023", text: "知足不辱，知止不殆，可以长久。", source: "《道德经》" },
  { id: "classics:024", text: "吾生也有涯，而知也无涯。", source: "《庄子·养生主》" },
  { id: "classics:025", text: "子非鱼，安知鱼之乐？", source: "《庄子·秋水》" },
  { id: "classics:026", text: "朝菌不知晦朔，蟪蛄不知春秋。", source: "《庄子·逍遥游》" },
  { id: "classics:027", text: "人生天地之间，若白驹之过隙，忽然而已。", source: "《庄子·知北游》" },
  { id: "classics:028", text: "相濡以沫，不如相忘于江湖。", source: "《庄子·大宗师》" },
  { id: "classics:029", text: "天将降大任于是人也，必先苦其心志，劳其筋骨。", source: "《孟子·告子下》" },
  { id: "classics:030", text: "富贵不能淫，贫贱不能移，威武不能屈。", source: "《孟子·滕文公下》" },
  { id: "classics:031", text: "民为贵，社稷次之，君为轻。", source: "《孟子·尽心下》" },
  { id: "classics:032", text: "老吾老以及人之老，幼吾幼以及人之幼。", source: "《孟子·梁惠王上》" },
  { id: "classics:033", text: "穷则独善其身，达则兼济天下。", source: "《孟子·尽心上》" },
  { id: "classics:034", text: "得道者多助，失道者寡助。", source: "《孟子·公孙丑下》" },
  { id: "classics:035", text: "生于忧患而死于安乐也。", source: "《孟子·告子下》" },
  { id: "classics:036", text: "关关雎鸠，在河之洲。窈窕淑女，君子好逑。", source: "《诗经·关雎》" },
  { id: "classics:037", text: "桃之夭夭，灼灼其华。", source: "《诗经·桃夭》" },
  { id: "classics:038", text: "昔我往矣，杨柳依依。今我来思，雨雪霏霏。", source: "《诗经·采薇》" },
  { id: "classics:039", text: "投我以木桃，报之以琼瑶。", source: "《诗经·木瓜》" },
  { id: "classics:040", text: "一日不见，如三秋兮。", source: "《诗经·采葛》" },
  { id: "classics:041", text: "青青子衿，悠悠我心。", source: "《诗经·子衿》" },
  { id: "classics:042", text: "他山之石，可以攻玉。", source: "《诗经·鹤鸣》" },
  { id: "classics:043", text: "天行健，君子以自强不息。", source: "《周易·乾》" },
  { id: "classics:044", text: "地势坤，君子以厚德载物。", source: "《周易·坤》" },
  { id: "classics:045", text: "穷则变，变则通，通则久。", source: "《周易·系辞下》" },
  { id: "classics:046", text: "积善之家，必有余庆；积不善之家，必有余殃。", source: "《周易·坤·文言》" },
  { id: "classics:047", text: "大学之道，在明明德，在亲民，在止于至善。", source: "《大学》" },
  { id: "classics:048", text: "物有本末，事有终始，知所先后，则近道矣。", source: "《大学》" },
  { id: "classics:049", text: "博学之，审问之，慎思之，明辨之，笃行之。", source: "《中庸》" },
  { id: "classics:050", text: "凡事预则立，不预则废。", source: "《中庸》" },
  { id: "classics:051", text: "玉不琢，不成器；人不学，不知道。", source: "《礼记·学记》" },
  { id: "classics:052", text: "学然后知不足，教然后知困。", source: "《礼记·学记》" },
  { id: "classics:053", text: "知己知彼，百战不殆。", source: "《孙子兵法·谋攻篇》" },
  { id: "classics:054", text: "兵无常势，水无常形。", source: "《孙子兵法·虚实篇》" },
  { id: "classics:055", text: "不战而屈人之兵，善之善者也。", source: "《孙子兵法·谋攻篇》" },
  { id: "classics:056", text: "人固有一死，或重于泰山，或轻于鸿毛。", source: "司马迁《史记·报任安书》" },
  { id: "classics:057", text: "桃李不言，下自成蹊。", source: "《史记·李将军列传》" },
  { id: "classics:058", text: "燕雀安知鸿鹄之志哉。", source: "《史记·陈涉世家》" },
  { id: "classics:059", text: "王侯将相宁有种乎。", source: "《史记·陈涉世家》" },
  { id: "classics:060", text: "智者千虑，必有一失；愚者千虑，必有一得。", source: "《史记·淮阴侯列传》" },
  { id: "classics:061", text: "风萧萧兮易水寒，壮士一去兮不复还。", source: "《史记·刺客列传》" },
  { id: "classics:062", text: "路漫漫其修远兮，吾将上下而求索。", source: "屈原《离骚》" },
  { id: "classics:063", text: "长太息以掩涕兮，哀民生之多艰。", source: "屈原《离骚》" },
  { id: "classics:064", text: "不积跬步，无以至千里；不积小流，无以成江海。", source: "《荀子·劝学》" },
  { id: "classics:065", text: "青，取之于蓝，而青于蓝。", source: "《荀子·劝学》" },
  { id: "classics:066", text: "锲而不舍，金石可镂。", source: "《荀子·劝学》" },
  { id: "classics:067", text: "满招损，谦受益。", source: "《尚书·大禹谟》" },
  { id: "classics:068", text: "防民之口，甚于防川。", source: "《国语·周语上》" },
  { id: "classics:069", text: "千丈之堤，以蝼蚁之穴溃。", source: "《韩非子·喻老》" },
  { id: "classics:070", text: "亡羊而补牢，未为迟也。", source: "《战国策·楚策四》" },
  { id: "classics:071", text: "前事之不忘，后事之师。", source: "《战国策·赵策一》" },
  { id: "classics:072", text: "近朱者赤，近墨者黑。", source: "傅玄《太子少傅箴》" },
  { id: "classics:073", text: "硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。", source: "《诗经·魏风·硕鼠》", full: "硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。\n\n硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。\n\n硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？" },
  { id: "classics:074", text: "彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？", source: "《诗经·王风·黍离》", full: "彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？\n\n彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？\n\n彼黍离离，彼稷之实。行迈靡靡，中心如噎。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？" },
  { id: "classics:075", text: "岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！", source: "《诗经·秦风·无衣》", full: "岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！\n\n岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！\n\n岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！" },
  { id: "classics:076", text: "蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。", source: "《诗经·秦风·蒹葭》", full: "蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。\n\n蒹葭萋萋，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。\n\n蒹葭采采，白露未已。所谓伊人，在水之涘。溯洄从之，道阻且右。溯游从之，宛在水中沚。" },
  { id: "classics:077", text: "风雨凄凄，鸡鸣喈喈。既见君子，云胡不夷？", source: "《诗经·郑风·风雨》", full: "风雨凄凄，鸡鸣喈喈。既见君子，云胡不夷？\n\n风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳？\n\n风雨如晦，鸡鸣不已。既见君子，云胡不喜？" },
  { id: "classics:078", text: "文王在上，于昭于天。周虽旧邦，其命维新。", source: "《诗经·大雅·文王》" },
  { id: "classics:079", text: "既明且哲，以保其身；夙夜匪解，以事一人。", source: "《诗经·大雅·烝民》" },
  { id: "classics:080", text: "战战兢兢，如临深渊，如履薄冰。", source: "《诗经·小雅·小旻》" },
  { id: "classics:081", text: "静女其姝，俟我于城隅。爱而不见，搔首踟蹰。", source: "《诗经·邶风·静女》" },
  { id: "classics:082", text: "瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨。", source: "《诗经·卫风·淇奥》" },
  { id: "classics:083", text: "死生契阔，与子成说。执子之手，与子偕老。", source: "《诗经·邶风·击鼓》" },
  { id: "classics:084", text: "呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。", source: "《诗经·小雅·鹿鸣》" },
  { id: "classics:085", text: "维天之命，於穆不已。于乎不显，文王之德之纯。", source: "《诗经·周颂·维天之命》" },
  { id: "classics:086", text: "不患人之不己知，患不知人也。", source: "《论语·学而》" },
  { id: "classics:087", text: "人而无信，不知其可也。", source: "《论语·为政》" },
  { id: "classics:088", text: "德不孤，必有邻。", source: "《论语·里仁》" },
  { id: "classics:089", text: "岁寒，然后知松柏之后凋也。", source: "《论语·子罕》" },
  { id: "classics:090", text: "人无远虑，必有近忧。", source: "《论语·卫灵公》" },
  { id: "classics:091", text: "鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。", source: "《孟子·告子上》", full: "鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。\n\n生亦我所欲，所欲有甚于生者，故不为苟得也；死亦我所恶，所恶有甚于死者，故患有所不辟也。如使人之所欲莫甚于生，则凡可以得生者，何不用也？使人之所恶莫甚于死者，则凡可以辟患者，何不为也？由是则生而有不用也，由是则可以辟患而有不为也。是故所欲有甚于生者，所恶有甚于死者。非独贤者有是心也，人皆有之，贤者能勿丧耳。" },
  { id: "classics:092", text: "恻隐之心，仁之端也；羞恶之心，义之端也；辞让之心，礼之端也；是非之心，智之端也。", source: "《孟子·公孙丑上》" },
  { id: "classics:093", text: "不违农时，谷不可胜食也；数罟不入洿池，鱼鳖不可胜食也。", source: "《孟子·梁惠王上》" },
  { id: "classics:094", text: "得天下有道：得其民，斯得天下矣。", source: "《孟子·离娄上》" },
  { id: "classics:095", text: "仰不愧于天，俯不怍于人。", source: "《孟子·尽心上》" },
  { id: "classics:096", text: "大器晚成，大音希声，大象无形。", source: "《道德经》" },
  { id: "classics:097", text: "天下难事，必作于易；天下大事，必作于细。", source: "《道德经》" },
  { id: "classics:098", text: "人法地，地法天，天法道，道法自然。", source: "《道德经》" },
  { id: "classics:099", text: "知者不言，言者不知。", source: "《道德经》" },
  { id: "classics:100", text: "天下莫柔弱于水，而攻坚强者莫之能胜。", source: "《道德经》" },
  { id: "classics:101", text: "为学日益，为道日损。", source: "《道德经》" },
  { id: "classics:102", text: "天下皆知美之为美，斯恶已；皆知善之为善，斯不善已。", source: "《道德经》" },
  { id: "classics:103", text: "北冥有鱼，其名为鲲。鲲之大，不知其几千里也；化而为鸟，其名为鹏。", source: "《庄子·逍遥游》", full: "北冥有鱼，其名为鲲。鲲之大，不知其几千里也；化而为鸟，其名为鹏。鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。是鸟也，海运则将徙于南冥。南冥者，天池也。" },
  { id: "classics:104", text: "昔者庄周梦为胡蝶，栩栩然胡蝶也，自喻适志与，不知周也。", source: "《庄子·齐物论》", full: "昔者庄周梦为胡蝶，栩栩然胡蝶也，自喻适志与，不知周也。俄然觉，则蘧蘧然周也。不知周之梦为胡蝶与，胡蝶之梦为周与？周与胡蝶，则必有分矣。此之谓物化。" },
  { id: "classics:105", text: "天地与我并生，而万物与我为一。", source: "《庄子·齐物论》" },
  { id: "classics:106", text: "人皆知有用之用，而莫知无用之用也。", source: "《庄子·人间世》" },
  { id: "classics:107", text: "井蛙不可以语于海者，拘于虚也；夏虫不可以语于冰者，笃于时也。", source: "《庄子·秋水》" },
  { id: "classics:108", text: "道虽迩，不行不至；事虽小，不为不成。", source: "《荀子·修身》" },
  { id: "classics:109", text: "天行有常，不为尧存，不为桀亡。", source: "《荀子·天论》" },
  { id: "classics:110", text: "君子博学而日参省乎己，则知明而行无过矣。", source: "《荀子·劝学》", full: "君子博学而日参省乎己，则知明而行无过矣。吾尝终日而思矣，不如须臾之所学也；吾尝跂而望矣，不如登高之博见也。" },
  { id: "classics:111", text: "君者，舟也；庶人者，水也。水则载舟，水则覆舟。", source: "《荀子·王制》" },
  { id: "classics:112", text: "人之性恶，其善者伪也。", source: "《荀子·性恶》" },
  { id: "classics:113", text: "一阴一阳之谓道。", source: "《周易·系辞上》" },
  { id: "classics:114", text: "易有太极，是生两仪，两仪生四象，四象生八卦。", source: "《周易·系辞上》" },
  { id: "classics:115", text: "同声相应，同气相求。", source: "《周易·乾·文言》" },
  { id: "classics:116", text: "天下同归而殊途，一致而百虑。", source: "《周易·系辞下》" },
  { id: "classics:117", text: "克明俊德，以亲九族。", source: "《尚书·尧典》" },
  { id: "classics:118", text: "无偏无党，王道荡荡；无党无偏，王道平平。", source: "《尚书·洪范》" },
  { id: "classics:119", text: "若网在纲，有条而不紊。", source: "《尚书·盘庚上》" },
  { id: "classics:120", text: "礼尚往来。往而不来，非礼也；来而不往，亦非礼也。", source: "《礼记·曲礼上》" },
  { id: "classics:121", text: "大道之行也，天下为公。选贤与能，讲信修睦。", source: "《礼记·礼运》" },
  { id: "classics:122", text: "苛政猛于虎也。", source: "《礼记·檀弓下》" },
  { id: "classics:123", text: "道德仁义，非礼不成。", source: "《礼记·曲礼上》" },
  { id: "classics:124", text: "一鼓作气，再而衰，三而竭。彼竭我盈，故克之。", source: "《左传·庄公十年》", full: "既克，公问其故。对曰：“夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。夫大国，难测也，惧有伏焉。吾视其辙乱，望其旗靡，故逐之。”" },
  { id: "classics:125", text: "多行不义，必自毙，子姑待之。", source: "《左传·隐公元年》" },
  { id: "classics:126", text: "人谁无过？过而能改，善莫大焉。", source: "《左传·宣公二年》" },
  { id: "classics:127", text: "居安思危，思则有备，有备无患。", source: "《左传·襄公十一年》" },
  { id: "classics:128", text: "辅车相依，唇亡齿寒。", source: "《左传·僖公五年》" },
  { id: "classics:129", text: "视人之国，若视其国；视人之家，若视其家；视人之身，若视其身。", source: "《墨子·兼爱中》" },
  { id: "classics:130", text: "杀一人谓之不义，必有一死罪矣；杀十人，十重不义，必有十死罪矣；杀百人，百重不义，必有百死罪矣。", source: "《墨子·非攻上》" },
  { id: "classics:131", text: "万事莫贵于义。", source: "《墨子·贵义》" },
  { id: "classics:132", text: "得时无怠，时不再来；天予不取，反为之灾。", source: "《国语·越语下》" },
  { id: "classics:133", text: "众心成城，众口铄金。", source: "《国语·周语下》" },
  { id: "classics:134", text: "吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。", source: "《战国策·齐策一》" },
  { id: "classics:135", text: "父母之爱子，则为之计深远。", source: "《战国策·赵策四》" },
  { id: "classics:136", text: "若士必怒，伏尸二人，流血五步，天下缟素，今日是也。", source: "《战国策·魏策四》" },
  { id: "classics:137", text: "兵者，诡道也。故能而示之不能，用而示之不用，近而示之远，远而示之近。", source: "《孙子兵法·始计篇》", full: "兵者，诡道也。故能而示之不能，用而示之不用，近而示之远，远而示之近；利而诱之，乱而取之，实而备之，强而避之，怒而挠之，卑而骄之，佚而劳之，亲而离之。攻其无备，出其不意。此兵家之胜，不可先传也。" },
  { id: "classics:138", text: "兵者，国之大事，死生之地，存亡之道，不可不察也。", source: "《孙子兵法·始计篇》" },
  { id: "classics:139", text: "主不可以怒而兴师，将不可以愠而致战；合于利而动，不合于利而止。", source: "《孙子兵法·火攻篇》" },
  { id: "classics:140", text: "吾盾之坚，物莫能陷也；吾矛之利，于物无不陷也。", source: "《韩非子·难一》", full: "楚人有鬻盾与矛者，誉之曰：“吾盾之坚，物莫能陷也。”又誉其矛曰：“吾矛之利，于物无不陷也。”或曰：“以子之矛陷子之盾，何如？”其人弗能应也。夫不可陷之盾与无不陷之矛，不可同世而立。" },
  { id: "classics:141", text: "儒以文乱法，侠以武犯禁。", source: "《韩非子·五蠹》" },
  { id: "classics:142", text: "事以密成，语以泄败。", source: "《韩非子·喻老》" },
  { id: "classics:143", text: "彼可取而代也。", source: "《史记·项羽本纪》" },
  { id: "classics:144", text: "强秦之所以不敢加兵于赵者，徒以吾二人在也。", source: "《史记·廉颇蔺相如列传》" },
  { id: "classics:145", text: "天下熙熙，皆为利来；天下攘攘，皆为利往。", source: "《史记·货殖列传》" },
  { id: "classics:146", text: "究天人之际，通古今之变，成一家之言。", source: "《史记·太史公自序》" },
  { id: "classics:147", text: "帝高阳之苗裔兮，朕皇考曰伯庸。摄提贞于孟陬兮，惟庚寅吾以降。", source: "屈原《离骚》", full: "帝高阳之苗裔兮，朕皇考曰伯庸。\n摄提贞于孟陬兮，惟庚寅吾以降。\n皇览揆余初度兮，肇锡余以嘉名：\n名余曰正则兮，字余曰灵均。\n纷吾既有此内美兮，又重之以修能。\n扈江离与辟芷兮，纫秋兰以为佩。\n汨余若将不及兮，恐年岁之不吾与。\n朝搴阰之木兰兮，夕揽洲之宿莽。\n日月忽其不淹兮，春与秋其代序。\n惟草木之零落兮，恐美人之迟暮。" },
  { id: "classics:148", text: "帝子降兮北渚，目眇眇兮愁予。袅袅兮秋风，洞庭波兮木叶下。", source: "屈原《九歌·湘夫人》" },
  { id: "classics:149", text: "古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身。", source: "《大学》", full: "古之欲明明德于天下者，先治其国；欲治其国者，先齐其家；欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意；欲诚其意者，先致其知；致知在格物。\n\n物格而后知至，知至而后意诚，意诚而后心正，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。" },
  { id: "classics:150", text: "天命之谓性，率性之谓道，修道之谓教。", source: "《中庸》", full: "天命之谓性，率性之谓道，修道之谓教。\n\n道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微，故君子慎其独也。\n\n喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。" },
];

/* ---------- Quotes: Chinese (genuine famous quotes; world quotes in standard Chinese translation) ---------- */
const QUOTES_ZH = [
  { id: "quotes:zh:001", text: "哪里有天才，我是把别人喝咖啡的工夫都用在工作上的。", author: "鲁迅" },
  { id: "quotes:zh:002", text: "其实地上本没有路，走的人多了，也便成了路。", author: "鲁迅《故乡》" },
  { id: "quotes:zh:003", text: "无端空耗别人的时间，其实是无异于谋财害命的。", author: "鲁迅" },
  { id: "quotes:zh:004", text: "横眉冷对千夫指，俯首甘为孺子牛。", author: "鲁迅《自嘲》" },
  { id: "quotes:zh:005", text: "时间就像海绵里的水，只要愿挤，总还是有的。", author: "鲁迅" },
  { id: "quotes:zh:006", text: "人类的悲欢并不相通，我只觉得他们吵闹。", author: "鲁迅《小杂感》" },
  { id: "quotes:zh:007", text: "哀其不幸，怒其不争。", author: "鲁迅" },
  { id: "quotes:zh:008", text: "真正的勇士敢于直面惨淡的人生，敢于正视淋漓的鲜血。", author: "鲁迅《记念刘和珍君》" },
  { id: "quotes:zh:009", text: "从来如此，便对吗？", author: "鲁迅《狂人日记》" },
  { id: "quotes:zh:010", text: "此后如竟没有炬火，我便是唯一的光。", author: "鲁迅《随感录四十一》" },
  { id: "quotes:zh:011", text: "无穷的远方，无数的人们，都和我有关。", author: "鲁迅《这也是生活》" },
  { id: "quotes:zh:012", text: "当我沉默着的时候，我觉得充实；我将开口，同时感到空虚。", author: "鲁迅《野草·题辞》" },
  { id: "quotes:zh:013", text: "猛兽总是独行，牛羊才成群结队。", author: "鲁迅" },
  { id: "quotes:zh:014", text: "黑夜给了我黑色的眼睛，我却用它寻找光明。", author: "顾城《一代人》" },
  { id: "quotes:zh:015", text: "卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭。", author: "北岛《回答》" },
  { id: "quotes:zh:016", text: "从明天起，做一个幸福的人，喂马、劈柴，周游世界。", author: "海子《面朝大海，春暖花开》" },
  { id: "quotes:zh:017", text: "人生若只如初见，何事秋风悲画扇。", author: "纳兰性德《木兰词》" },
  { id: "quotes:zh:018", text: "心有猛虎，细嗅蔷薇。", author: "萨松（余光中 译）" },
  { id: "quotes:zh:019", text: "生如夏花之绚烂，死如秋叶之静美。", author: "泰戈尔《飞鸟集》（郑振铎 译）" },
  { id: "quotes:zh:020", text: "如果你因失去了太阳而流泪，那么你也将失去群星了。", author: "泰戈尔《飞鸟集》" },
  { id: "quotes:zh:021", text: "世界以痛吻我，要我报之以歌。", author: "泰戈尔《飞鸟集》" },
  { id: "quotes:zh:022", text: "未经审视的人生不值得过。", author: "苏格拉底" },
  { id: "quotes:zh:023", text: "我唯一知道的，就是我一无所知。", author: "苏格拉底" },
  { id: "quotes:zh:024", text: "认识你自己。", author: "古希腊德尔斐神谕" },
  { id: "quotes:zh:025", text: "吾爱吾师，吾更爱真理。", author: "亚里士多德" },
  { id: "quotes:zh:026", text: "给我一个支点，我就能撬起整个地球。", author: "阿基米德" },
  { id: "quotes:zh:027", text: "人不能两次踏进同一条河流。", author: "赫拉克利特" },
  { id: "quotes:zh:028", text: "人生而自由，却无往不在枷锁之中。", author: "卢梭《社会契约论》" },
  { id: "quotes:zh:029", text: "我思故我在。", author: "笛卡尔" },
  { id: "quotes:zh:030", text: "人是一根会思考的芦苇。", author: "帕斯卡尔" },
  { id: "quotes:zh:031", text: "知识就是力量。", author: "培根" },
  { id: "quotes:zh:032", text: "读史使人明智，读诗使人灵秀。", author: "培根《论读书》" },
  { id: "quotes:zh:033", text: "如果冬天来了，春天还会远吗？", author: "雪莱《西风颂》" },
  { id: "quotes:zh:034", text: "走自己的路，让别人说去吧。", author: "但丁" },
  { id: "quotes:zh:035", text: "幸福的家庭都是相似的，不幸的家庭各有各的不幸。", author: "托尔斯泰《安娜·卡列尼娜》" },
  { id: "quotes:zh:036", text: "一个人可以被毁灭，但不能被打败。", author: "海明威《老人与海》" },
  { id: "quotes:zh:037", text: "世界上只有一种英雄主义，那就是在认清生活的真相之后依然热爱生活。", author: "罗曼·罗兰" },
  { id: "quotes:zh:038", text: "人最宝贵的是生命。生命对人来说只有一次。", author: "奥斯特洛夫斯基《钢铁是怎样炼成的》" },
  { id: "quotes:zh:039", text: "冬天从这里夺去的，春天会交还给你。", author: "海涅" },
  { id: "quotes:zh:040", text: "存在先于本质。", author: "萨特" },
  { id: "quotes:zh:041", text: "勿以恶小而为之，勿以善小而不为。", author: "刘备（见《三国志》）" },
  { id: "quotes:zh:042", text: "非淡泊无以明志，非宁静无以致远。", author: "诸葛亮《诫子书》" },
  { id: "quotes:zh:043", text: "鞠躬尽瘁，死而后已。", author: "诸葛亮《后出师表》" },
  { id: "quotes:zh:044", text: "先天下之忧而忧，后天下之乐而乐。", author: "范仲淹《岳阳楼记》" },
  { id: "quotes:zh:045", text: "人生自古谁无死，留取丹心照汗青。", author: "文天祥《过零丁洋》" },
  { id: "quotes:zh:046", text: "业精于勤，荒于嬉；行成于思，毁于随。", author: "韩愈《进学解》" },
  { id: "quotes:zh:047", text: "少年易老学难成，一寸光阴不可轻。", author: "朱熹《偶成》" },
  { id: "quotes:zh:048", text: "问渠那得清如许？为有源头活水来。", author: "朱熹《观书有感》" },
  { id: "quotes:zh:049", text: "书山有路勤为径，学海无涯苦作舟。", author: "韩愈" },
  { id: "quotes:zh:050", text: "宝剑锋从磨砺出，梅花香自苦寒来。", author: "《警世贤文》" },
  { id: "quotes:zh:051", text: "世上无难事，只怕有心人。", author: "民间谚语" },
  { id: "quotes:zh:052", text: "路遥知马力，日久见人心。", author: "民间谚语" },
  { id: "quotes:zh:053", text: "三个臭皮匠，顶个诸葛亮。", author: "民间谚语" },
  { id: "quotes:zh:054", text: "星星之火，可以燎原。", author: "毛泽东" },
  { id: "quotes:zh:055", text: "没有调查，就没有发言权。", author: "毛泽东" },
  { id: "quotes:zh:056", text: "好好学习，天天向上。", author: "毛泽东（题词）" },
  { id: "quotes:zh:057", text: "世界是你们的，也是我们的，但是归根结底是你们的。", author: "毛泽东" },
  { id: "quotes:zh:058", text: "为中华之崛起而读书。", author: "周恩来" },
  { id: "quotes:zh:059", text: "不管黑猫白猫，抓住老鼠就是好猫。", author: "邓小平" },
  { id: "quotes:zh:060", text: "科学技术是第一生产力。", author: "邓小平" },
  { id: "quotes:zh:061", text: "发展才是硬道理。", author: "邓小平" },
  { id: "quotes:zh:062", text: "想象力比知识更重要。", author: "爱因斯坦" },
  { id: "quotes:zh:063", text: "生活就像骑自行车，要保持平衡，你必须不断前进。", author: "爱因斯坦" },
  { id: "quotes:zh:064", text: "宇宙中最难以理解的是，宇宙居然是可以被理解的。", author: "爱因斯坦" },
  { id: "quotes:zh:065", text: "天才就是百分之一的灵感，加上百分之九十九的汗水。", author: "爱迪生" },
  { id: "quotes:zh:066", text: "我没有失败，我只是发现了一万种行不通的方法。", author: "爱迪生" },
  { id: "quotes:zh:067", text: "如果我看得更远，那是因为我站在巨人的肩膀上。", author: "牛顿" },
  { id: "quotes:zh:068", text: "数学是科学的女王。", author: "高斯" },
  { id: "quotes:zh:069", text: "万物皆数。", author: "毕达哥拉斯学派" },
  { id: "quotes:zh:070", text: "时间是最伟大的作者，总会写出完美的结局。", author: "卓别林" },
  { id: "quotes:zh:071", text: "人生近看是悲剧，远看是喜剧。", author: "卓别林" },
  { id: "quotes:zh:072", text: "简单是终极的复杂。", author: "达·芬奇" },
  { id: "quotes:zh:073", text: "求知若饥，虚心若愚。", author: "乔布斯（引自《全球概览》）" },
  { id: "quotes:zh:074", text: "你的时间有限，不要浪费于重复别人的生活。", author: "乔布斯" },
  { id: "quotes:zh:075", text: "设计不只是外观和感觉，设计是它如何工作。", author: "乔布斯" },
  { id: "quotes:zh:076", text: "生命如同故事，重要的不是它有多长，而是它有多好。", author: "塞内卡" },
];

